/** authoritative in-memory parcel deeds + listings + treasury, mirroring the `tiles`
 *  pattern: the DB is the durable copy, these Maps are what handlers read/write. */
const qParcelIns = db.prepare('INSERT OR REPLACE INTO parcels(id,owner,map,name,tiles,createdAt) VALUES(?,?,?,?,?,?)');
const qParcelDel = db.prepare('DELETE FROM parcels WHERE id=?');
const qParcelAll = db.prepare('SELECT * FROM parcels');
const qParcelListIns = db.prepare('INSERT OR REPLACE INTO parcel_listings(id,seller,map,priceItem,priceQty,createdAt) VALUES(?,?,?,?,?,?)');
const qParcelListDel = db.prepare('DELETE FROM parcel_listings WHERE id=?');
const qParcelListAll = db.prepare('SELECT * FROM parcel_listings');
const qTreasuryAdd = db.prepare('INSERT INTO treasury(item,qty,updated) VALUES(?,?,?) ' +
  'ON CONFLICT(item) DO UPDATE SET qty=treasury.qty+excluded.qty, updated=excluded.updated');
const qTreasuryAll = db.prepare('SELECT item,qty FROM treasury');
const parcels = new Map();        // id -> {id, owner, map, name, tiles:[{x,y}], createdAt}
const parcelListings = new Map(); // id (== parcel id) -> {id, seller, map, priceItem, priceQty, createdAt}
(function loadParcels() {
  for (const r of qParcelAll.all()) {
    let tiles = null;
    try { tiles = JSON.parse(r.tiles); } catch (e) { tiles = null; }
    const v = Parcels.validateDeed(tiles, r.name);
    if (!v.ok) continue;                       // a corrupt row can never become a sellable deed
    parcels.set(r.id, { id: r.id, owner: r.owner, map: r.map, name: v.name, tiles: v.tiles, createdAt: r.createdAt });
  }
  for (const r of qParcelListAll.all()) {
    if (!parcels.has(r.id)) { qParcelListDel.run(r.id); continue; }  // listing without a deed is junk
    parcelListings.set(r.id, { id: r.id, seller: r.seller, map: r.map, priceItem: r.priceItem, priceQty: r.priceQty, createdAt: r.createdAt });
  }
  console.log(`[world] ${parcels.size} parcel deed(s) and ${parcelListings.size} parcel listing(s) restored`);
})();
/** Set of every tile currently inside a deed: "map:x:y". Enforced at mint so two deeds
 *  can never contain the same tile — without this, selling one deed would silently
 *  corrupt the other. Rebuilt from `parcels` whenever deeds change. */
function deedTileSet() {
  const s = new Set();
  for (const d of parcels.values()) for (const t of d.tiles) s.add(d.map + ':' + t.x + ':' + t.y);
  return s;
}
/** Credit the game treasury (monetization: 2.5% of every deed sale). Per-item rows so
 *  a deed priced in any catalog item yields a fee in that same item. */
function treasuryCredit(item, qty) {
  if (typeof item !== 'string' || !item || !(qty > 0)) return;
  qTreasuryAdd.run(item, qty | 0, Date.now());
}
/** Public treasury totals for /api/stats — amounts only, no player data. */
function treasuryTotals() {
  const out = {};
  for (const r of qTreasuryAll.all()) out[r.item] = r.qty | 0;
  return out;
}

// ---------- STRATUM sinks: Earth Requisition + Structure Rush --------------------------
// See src/token-sink.js's header. Burned STRATUM is the "gone forever" half of every
// sink spend — a single global running total, never per-player (nobody is owed it
// back, so there is nothing to key by player). The treasury half reuses the SAME
// treasury table shop/parcel fees already feed, under the 'STRATUM' item key — one place
// to look for "how much real fee revenue has this world generated," across every
// source, in-game resources and STRATUM alike.
const qBurnGet = db.prepare('SELECT total FROM token_burned WHERE id=?');
const qBurnUpsert = db.prepare(
  'INSERT INTO token_burned(id,total,updated) VALUES(?,?,?) ' +
  'ON CONFLICT(id) DO UPDATE SET total=excluded.total, updated=excluded.updated');
function burnedTotal() {
  const row = qBurnGet.get('global');
  return row ? (row.total | 0) : 0;
}
/** Permanently destroy `n` STRATUM (adds to the global burned counter) and credit the
 *  in-game treasury with the rest of a sink's split, in one call — every sink handler
 *  ends with exactly this. Never touches any player's ledger; the caller already
 *  deducted the full spend from `pending` before calling this. */
function applyBurnSplit(n) {
  const split = TokenSink.splitBurn(n, TOKEN_BURN_BPS);
  if (split.burned > 0) qBurnUpsert.run('global', burnedTotal() + split.burned, Date.now());
  if (split.treasury > 0) treasuryCredit('STRATUM', split.treasury);
  return split;
}

function applyOnChainSplit(gross) {
  const split = TokenSink.splitOnChain(gross, TOKEN_BURN_BPS);
  if (split.burned > 0) qBurnUpsert.run('global', burnedTotal() + split.burned, Date.now());
  if (split.treasury > 0) treasuryCredit('STRATUM', split.treasury);
  return split;
}

function sinkOnChainLive() {
  return SINK_ONCHAIN && ChainAdapter.isConfigured(claimEnv());
}

db.exec(`CREATE TABLE IF NOT EXISTS sink_txs(
  txHash TEXT PRIMARY KEY, k TEXT NOT NULL, amount INTEGER NOT NULL, createdAt INTEGER NOT NULL);`);
const qSinkTxGet = db.prepare('SELECT k FROM sink_txs WHERE txHash=?');
const qSinkTxIns = db.prepare('INSERT INTO sink_txs(txHash,k,amount,createdAt) VALUES(?,?,?,?)');
const sinkQuotes = new Map();
const SINK_QUOTE_MS = 90 * 1000;

/** On-chain half of a sink. Ledger burn already happened. This moves real STRATUM
 *  to the incinerator (the transfer tax feeds holder GLDX) and swaps the earmarked
 *  treasury slice into GLDX to fund play-claims. Off unless STRATUM_SINK_ONCHAIN=1,
 *  and it refuses if the treasury would no longer cover outstanding STRATUM claims. */
let sinkRunning = false;
function scheduleOnChainSink(burnWhole, swapWhole) {
  if ((burnWhole | 0) > 0) counterSet('chain_burn_owed', counterOf('chain_burn_owed') + (burnWhole | 0));
  if ((swapWhole | 0) > 0) counterSet('gldx_earmark', counterOf('gldx_earmark') + (swapWhole | 0));
  if (process.env.STRATUM_SINK_ONCHAIN !== '1') return;
  if (sinkRunning) return;
  sinkRunning = true;
  executeOnChainSink().catch((e) => {
    console.log('[sink] ' + (e && e.message ? e.message : e));
  }).finally(() => { sinkRunning = false; });
}
async function executeOnChainSink() {
  const env = claimEnv();
  if (!ChainAdapter.isConfigured(env)) return;
  const owed = counterOf('chain_burn_owed');
  const mark = counterOf('gldx_earmark');
  const signer = ChainAdapter.signerAddress(env);
  if (!signer) return;
  const bal = await ChainAdapter.readBalance(signer, env);
  if (!bal.ok) {
    console.log('[sink] treasury balance unread: ' + (bal.detail || bal.reason));
    return;
  }
  const pending = (qLedgerTotal.get().t | 0);
  if ((bal.balance | 0) - owed - mark < pending) {
    console.log('[sink] holding the on-chain burn: treasury ' + bal.balance +
      ' would not cover pending ' + pending + ' after burning ' + owed + ' and swapping ' + mark);
    return;
  }
  if (owed > 0) {
    const raw = (BigInt(owed) * 1000000n).toString();
    const burned = await ChainAdapter.transferRaw(Gldx.INCINERATOR, COMMERCE.tokenMint, raw, 6, env);
    if (!burned.ok) {
      console.log('[sink] burn not sent: ' + burned.reason + ' ' + (burned.detail || ''));
      return;
    }
    counterSet('chain_burn_owed', 0);
    console.log('[sink] burned ' + owed + ' STRATUM on-chain ' + burned.txHash);
  }
  const em = counterOf('gldx_earmark');
  if (em >= Gldx.MIN_SWAP) {
    const sw = await ChainAdapter.swapStratumForGldx(em, Gldx.GLDX_MINT, env);
    if (!sw.ok) {
      console.log('[sink] GLDX swap not sent: ' + sw.reason + ' ' + (sw.detail || ''));
      return;
    }
    counterSet('gldx_earmark', 0);
    console.log('[sink] swapped ' + em + ' STRATUM for GLDX ' + (sw.txHash || ''));
    await fundGldxClaims();
  }
}
async function fundGldxClaims() {
  const env = claimEnv();
  if (!ChainAdapter.isConfigured(env)) return;
  const signer = ChainAdapter.signerAddress(env);
  if (!signer) return;
  const bal = await ChainAdapter.readMintBalance(signer, Gldx.GLDX_MINT, Gldx.DECIMALS, env);
  if (!bal.ok) return;
  const rows = qGldxAll.all();
  const next = Gldx.allocate(rows, bal.balanceRaw | 0);
  if (next.moved <= 0) return;
  for (const row of next.rows) qGldxSet.run(row.pending, row.payable, Date.now(), row.key);
  for (const o of clients.values()) {
    if (!o.key) continue;
    const g = ledgerOf(o.key);
    o.gldxPending = g.gldxPending;
    o.gldxPayable = g.gldxPayable;
    try {
      o.send({
        t: 'gldx', gldxPending: g.gldxPending, gldxPayable: g.gldxPayable,
        gldxText: Gldx.format(g.gldxPending), gldxReadyText: Gldx.format(g.gldxPayable)
      });
    } catch (e) {}
  }
}

function finishOnChainShip(c, amount) {
  const split = applyOnChainSplit(amount);
  scheduleOnChainSink(split.burned, Gldx.earmarkOf(split.treasury));
  return split;
}

function broadcastRequisition(c, amount) {
  if (amount < 50) return;
  const quota = burnedTotal();
  for (const o of clients.values()) {
    if (o.ready && o.key !== c.key) o.send({ t: 'requisition-broadcast', by: c.name, amount: amount, colonyQuota: quota });
  }
}

function handleOnChainRequisition(c, msg) {
  if (!c.tokenWallet) {
    return c.send({ t: 'requisitioned', ok: false, err: 'link a wallet first' });
  }
  if (typeof msg.txHash === 'string' && msg.txHash.length) {
    confirmOnChainRequisition(c, msg);
    return;
  }
  const amount = (msg.amount === undefined) ? ONCHAIN_DEFAULT_SHIP
    : (isFin(msg.amount) ? Math.trunc(msg.amount) : -1);
  const v = TokenSink.validateRequisition(amount, amount);
  if (!v.ok) return c.send({ t: 'requisitioned', ok: false, err: v.error });
  const env = claimEnv();
  ChainAdapter.buildPlayerTransfer(c.tokenWallet, v.amount, env).then((built) => {
    if (!built.ok) {
      return c.send({
        t: 'requisitioned', ok: false,
        err: built.reason === 'insufficient_balance'
          ? 'claim STRATUM first — ship from your wallet'
          : (built.detail || built.reason)
      });
    }
    sinkQuotes.set(c.key, { kind: 'requisition', amount: v.amount, expires: Date.now() + SINK_QUOTE_MS });
    const split = TokenSink.splitOnChain(v.amount, TOKEN_BURN_BPS);
    c.send({
      t: 'requisition-sign', amount: v.amount, tx: built.tx, message: built.message,
      tax: split.tax, arrived: split.arrived, burned: split.burned, treasury: split.treasury
    });
  }).catch(() => {
    try { c.send({ t: 'requisitioned', ok: false, err: 'could not build the shipment' }); } catch (e) {}
  });
}

function confirmOnChainRequisition(c, msg) {
  const q = sinkQuotes.get(c.key);
  if (!q || q.kind !== 'requisition' || Date.now() > q.expires) {
    return c.send({ t: 'requisitioned', ok: false, err: 'sign again — quote expired' });
  }
  if (qSinkTxGet.get(msg.txHash)) {
    return c.send({ t: 'requisitioned', ok: false, err: 'already shipped' });
  }
  ChainAdapter.verifyIncomingTransfer(msg.txHash, c.tokenWallet, q.amount, claimEnv()).then((ver) => {
    if (!ver.ok) {
      return c.send({ t: 'requisitioned', ok: false, err: ver.detail || ver.reason });
    }
    qSinkTxIns.run(msg.txHash, c.key, q.amount, Date.now());
    sinkQuotes.delete(c.key);
    const split = finishOnChainShip(c, q.amount);
    const quota = burnedTotal();
    const pending = ledgerOf(c.key).pending | 0;
    c.send({
      t: 'requisitioned', ok: true, amount: q.amount, burned: split.burned, treasury: split.treasury,
      tax: split.tax, tokenPending: pending, colonyQuota: quota, onChain: true, txHash: msg.txHash
    });
    broadcastRequisition(c, q.amount);
    checkAchievements(c);
    refreshHolderBonus(c);
  }).catch(() => {
    try { c.send({ t: 'requisitioned', ok: false, err: 'could not confirm the shipment' }); } catch (e) {}
  });
}

function quoteRushFor(c, msg) {
  let rkey;
  if (isFin(msg.x) && isFin(msg.y)) {
    const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
    if (x === null || y === null) return { err: 'bounds' };
    rkey = structKey(c.map, x, y);
  } else {
    const id = cleanText(msg.id, 64);
    if (!id) return { err: 'no structure there' };
    rkey = id;
  }
  const struct = structures.get(rkey);
  if (!struct || struct.map !== c.map) return { err: 'no structure there' };
  if (struct.owner !== c.key) return { err: 'not yours' };
  const rdx = struct.x - c.x, rdy = struct.y - c.y;
  if (rdx * rdx + rdy * rdy > REACH * REACH) return { err: 'reach', x: struct.x, y: struct.y };
  const def = Idle.structureOf(struct.kind);
  if (!def) return { err: 'unknown structure' };
  const rnow = Date.now();
  const already = Idle.accrued(struct, rnow);
  const quote = TokenSink.rushCost(already, def.capacity, RUSH_COST_PER_UNIT);
  if (quote.cost <= 0) return { err: 'already full' };
  return { struct: struct, def: def, rkey: rkey, rnow: rnow, quote: quote };
}

function applyRushFill(c, info) {
  const rRes = Idle.collect(info.struct, c.inv, info.rnow);
  const rInv = Object.assign({}, rRes.inv);
  rInv[info.def.produces] = (rInv[info.def.produces] || 0) + info.quote.gained;
  c.inv = rInv;
  structures.set(info.rkey, rRes.struct);
  qStruct.run(rRes.struct.id, rRes.struct.kind, rRes.struct.map, rRes.struct.x, rRes.struct.y, rRes.struct.owner, rRes.struct.builtAt, rRes.struct.lastCollectedAt);
  stateSave(c);
  return rRes;
}

function handleOnChainRush(c, msg) {
  if (!c.tokenWallet) return c.send({ t: 'rushed', err: 'link a wallet first' });
  if (typeof msg.txHash === 'string' && msg.txHash.length) {
    confirmOnChainRush(c, msg);
    return;
  }
  const info = quoteRushFor(c, msg);
  if (info.err) return c.send({ t: 'rushed', err: info.err, x: info.x, y: info.y });
  ChainAdapter.buildPlayerTransfer(c.tokenWallet, info.quote.cost, claimEnv()).then((built) => {
    if (!built.ok) {
      return c.send({
        t: 'rushed', err: built.reason === 'insufficient_balance'
          ? 'claim STRATUM first — rush from your wallet'
          : (built.detail || built.reason),
        cost: info.quote.cost
      });
    }
    sinkQuotes.set(c.key, {
      kind: 'rush', amount: info.quote.cost, x: info.struct.x, y: info.struct.y,
      rkey: info.rkey, expires: Date.now() + SINK_QUOTE_MS
    });
    const split = TokenSink.splitOnChain(info.quote.cost, TOKEN_BURN_BPS);
    c.send({
      t: 'rush-sign', x: info.struct.x, y: info.struct.y, cost: info.quote.cost,
      tx: built.tx, message: built.message,
      tax: split.tax, burned: split.burned, treasury: split.treasury
    });
  }).catch(() => {
    try { c.send({ t: 'rushed', err: 'could not build the rush' }); } catch (e) {}
  });
}

function confirmOnChainRush(c, msg) {
  const q = sinkQuotes.get(c.key);
  if (!q || q.kind !== 'rush' || Date.now() > q.expires) {
    return c.send({ t: 'rushed', err: 'sign again — quote expired' });
  }
  if (qSinkTxGet.get(msg.txHash)) return c.send({ t: 'rushed', err: 'already shipped' });
  ChainAdapter.verifyIncomingTransfer(msg.txHash, c.tokenWallet, q.amount, claimEnv()).then((ver) => {
    if (!ver.ok) return c.send({ t: 'rushed', err: ver.detail || ver.reason, cost: q.amount });
    qSinkTxIns.run(msg.txHash, c.key, q.amount, Date.now());
    sinkQuotes.delete(c.key);
    const split = finishOnChainShip(c, q.amount);
    const info = quoteRushFor(c, { x: q.x, y: q.y });
    let gained = 0;
    let resource = null;
    let x = q.x, y = q.y;
    if (!info.err) {
      const rRes = applyRushFill(c, info);
      gained = rRes.gained + info.quote.gained;
      resource = info.def.produces;
      x = info.struct.x;
      y = info.struct.y;
    }
    c.send({
      t: 'rushed', x: x, y: y, resource: resource,
      gained: gained, cost: q.amount, burned: split.burned, treasury: split.treasury,
      inv: c.inv, tokenPending: c.tokenPending, tokenBurned: burnedTotal(), onChain: true, txHash: msg.txHash
    });
    if (gained > 0) checkAchievements(c);
    refreshHolderBonus(c);
  }).catch(() => {
    try { c.send({ t: 'rushed', err: 'could not confirm the rush' }); } catch (e) {}
  });
}

// ---------- economy instrumentation: faucet vs sink dashboard ----------------
// Read-only, no new tables, computed from existing token_ledger + treasuryTotals +
// burnedTotal. This is the "no faucet vs sink dashboard" gap this hardening pass
// closes: operators and players can see pending supply, burned supply, and the
// distribution of pending balances without any chain or mint.
const qLedgerStats = db.prepare('SELECT COALESCE(SUM(pending),0) AS totalPending, COALESCE(SUM(claimed),0) AS totalClaimed, COUNT(*) AS n, COALESCE(AVG(pending),0) AS avgPending FROM token_ledger');
const qPendingAll = db.prepare('SELECT pending FROM token_ledger');
function economyStats() {
  try {
    const row = qLedgerStats.get();
    const totalPending = row ? (row.totalPending | 0) : 0;
    const totalClaimed = row ? (row.totalClaimed | 0) : 0;
    const n = row ? (row.n | 0) : 0;
    const avgPendingPerPlayer = n ? +Number(row.avgPending || 0).toFixed(2) : 0;
    var buckets = { '0': 0, '1-10': 0, '11-50': 0, '51-200': 0, '201-1000': 0, '1000+': 0 };
    try {
      var rows = qPendingAll.all();
      for (var i = 0; i < rows.length; i++) {
        var v = rows[i].pending | 0;
        if (v === 0) buckets['0']++;
        else if (v <= 10) buckets['1-10']++;
        else if (v <= 50) buckets['11-50']++;
        else if (v <= 200) buckets['51-200']++;
        else if (v <= 1000) buckets['201-1000']++;
        else buckets['1000+']++;
      }
    } catch (e2) { /* histogram is best-effort */ }
    var treas = treasuryTotals();
    var burned = burnedTotal();
    var vault = vaultStats();
    return {
      faucet: { totalPending: totalPending, totalClaimed: totalClaimed, avgPendingPerPlayer: avgPendingPerPlayer },
      sink: { burnedTotal: burned, treasuryFees: treas, treasurySTRM: treas.STRATUM | 0 },
      vault: { tvl: vault.tvl, depositors: vault.depositors },
      upkeep: { burnedWeek: counterOf('upkeep_week_burned'), dividendsWeek: counterOf('upkeep_week_divs') },
      pendingHistogram: buckets
    };
  } catch (e) {
    return {
      faucet: { totalPending: 0, totalClaimed: 0, avgPendingPerPlayer: 0 },
      sink: { burnedTotal: 0, treasuryFees: {}, treasurySTRM: 0 },
      vault: { tvl: 0, depositors: 0 },
      upkeep: { burnedWeek: 0, dividendsWeek: 0 },
      pendingHistogram: { '0': 0, '1-10': 0, '11-50': 0, '51-200': 0, '201-1000': 0, '1000+': 0 }
    };
  }
}
/** Remove one tile from every deed containing it (called on tile release). A deed
 *  reduced to zero tiles dissolves; a dissolved listing just delists (nothing was
 *  ever escrowed away — the deed is a view, so there is nothing to return). */
function deedsDropTile(map, x, y) {
  const k = map + ':' + x + ':' + y;
  for (const [id, d] of [...parcels]) {
    if (d.map !== map) continue;
    const kept = d.tiles.filter(t => (t.x + ':' + t.y) !== (x + ':' + y));
    if (kept.length === d.tiles.length) continue;
    if (!kept.length) {
      parcels.delete(id);
      qParcelDel.run(id);
      if (parcelListings.has(id)) { parcelListings.delete(id); qParcelListDel.run(id); }
    } else {
      d.tiles = kept;
      qParcelIns.run(id, d.owner, d.map, d.name, JSON.stringify(kept), d.createdAt);
    }
  }
}

/** Credit `qty` of `item` to player `key`, whether they are online right now or not.
 *  Online: straight into their live inventory (same shape `gain()` uses elsewhere).
 *  Offline: read-modify-write their persisted row through the same qState/stateSave
 *  machinery the rest of the server uses to checkpoint a connected player — this is the
 *  "seller/offerer may be offline" case both shops and trade require. A missing state row
 *  should not happen (only a player who has connected before can own a listing or send a
 *  trade offer to begin with) but is handled defensively rather than assumed away. */
function creditPlayer(key, item, qty) {
  for (const c of clients.values()) {
    if (c.ready && c.key === key) { gain(c, item, qty); stateSave(c); return; }
  }
  const st = qStateGet.get(key);
  if (!st) return;
  let inv;
  try { inv = JSON.parse(st.inv); } catch (e) { inv = {}; }
  if (!inv || typeof inv !== 'object') inv = {};
  inv[item] = (inv[item] || 0) + qty;
  qState.run(key, st.map, st.x, st.y, st.hp, st.kills, JSON.stringify(inv), st.tool);
}

/** Tell `key` something happened to their shop/trade, but only if they are online right
 *  now — an offline player already got their goods via creditPlayer() above and will see
 *  the result of that the next time they play; there is nothing to push to a closed socket. */
function notifyPlayer(key, obj) {
  for (const c of clients.values()) if (c.ready && c.key === key) { c.send(obj); return; }
}

const world = new World(db);

// ---------- static files ---------------------------------------------------
const MIME = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.json': 'application/json',
  '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
  '.webp': 'image/webp', '.ico': 'image/x-icon', '.svg': 'image/svg+xml'
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  let p = decodeURIComponent(url.pathname);

  if (p === '/api/stats') {
    const bodies = {};
    for (const m of T.MAPS) {
      const c = countClaims(m.id);
      bodies[m.id] = { name: m.name, claimed: c, pct: +((c / (W * H)) * 100).toFixed(5) };
    }
    const body = JSON.stringify({
      world: { w: W, h: H, tiles: W * H },
      maps: bodies,
      claimed: tiles.size,
      online: [...clients.values()].filter(c => c.ready).length,
      playersEver: qPlayCount.get().n,
      volatile: world.stats(),
      spawn: T.spawnPoint(0),
      // In-game fee vault (soft resources taken as a cut of priced sales, PLUS STRATUM
      // from sink spends — see treasury.STRATUM below).
      treasury: treasuryTotals(),
      // On-chain treasury wallet (public address) + fee knobs — no secrets.
      treasuryWallet: COMMERCE.treasuryAddress,
      fees: Object.assign({
        parcelBps: PARCEL_FEE_BPS, shopBps: SHOP_FEE_BPS, tokenBurnBps: TOKEN_BURN_BPS,
        rushCostPerUnit: RUSH_COST_PER_UNIT,
        salvageRefundBps: SALVAGE_REFUND_BPS, maxCraftBatch: Crafting.MAX_BATCH
      }, payoutPublic()),
      // Total STRATUM ever burned via a sink — the actual "silver shipped to Earth" mission
      // metric this game's whole story is about. Never decreases; nothing owed for it.
      colonyQuota: burnedTotal(),
      // The community-wide yield bonus every player currently earns (src/colony-
      // milestone.js) — the same for everyone, at any given moment, regardless of who
      // did the spending. `next` is null once the final tier is reached.
      colonyMilestone: (function () {
        const q = burnedTotal();
        return {
          name: ColonyMilestone.milestoneFor(q).name,
          multiplier: ColonyMilestone.multiplierFor(q),
          next: ColonyMilestone.nextMilestone(q)
        };
      })(),
      commerce: TokenConfig.publicConfig(COMMERCE),
      // Economy instrumentation (faucet vs sink) — read-only dashboard added by
      // hardening pass; does not change any existing field above.
      economy: economyStats()
    }, null, 2);
    res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' });
    return res.end(body);
  }

  if (p === '/api/palettes') {
    // Read-only, no wire protocol of its own — same "plain fetch" precedent as
    // /api/leaderboard. Lets the gate screen render swatches BEFORE the player has
    // typed a name and connected, when there is no client yet to send 'hello'.
    const body = JSON.stringify(CU.ALL_PALETTES.map(p2 => ({ id: p2.id, name: p2.name, bodyHue: p2.bodyHue, trimHue: p2.trimHue })));
    res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' });
    return res.end(body);
  }

  if (p === '/api/leaderboard') {
    // Land: sort the already-maintained per-owner counter — O(distinct owners), never a
    // scan of `tiles` (1,048,576 tiles/map). `ownerCounts` includes owners who are not
    // currently online, because it is seeded from the durable `tiles` table at boot and
    // kept live by the same increments as `claimCounts`; a name lookup per top-N owner
    // (qPlayGet) covers players who logged off between claiming and this request.
    const land = [...ownerCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, LB_N)
      .map(([owner, count]) => {
        const row = qPlayGet.get(owner);
        return { name: (row && row.name) || 'WANDERER', tag: T.keyTag(owner), count };
      });

    // Kills/level: world.hunters is the existing live progression table — reused as-is,
    // same non-reversible key tag world.stats() already publishes. This is in-memory only
    // (players who haven't connected since the last restart won't appear), matching the
    // precedent /api/stats already sets for `volatile.hunters`.
    const hunters = world.stats().hunters;
    const kills = hunters.slice().sort((a, b) => b.kills - a.kills).slice(0, LB_N)
      .map(h => ({ name: h.name || 'WANDERER', tag: h.k, kills: h.kills, level: h.level }));
    const level = hunters.slice().sort((a, b) => (b.level - a.level) || (b.xp - a.xp)).slice(0, LB_N)
      .map(h => ({ name: h.name || 'WANDERER', tag: h.k, level: h.level, xp: h.xp }));

    const body = JSON.stringify({ land, kills, level }, null, 2);
    res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' });
    return res.end(body);
  }

  if (p === '/') p = '/landing.html';
  if (p === '/play') p = '/index.html';
  const file = path.join(PUB, path.normalize(p));
  if (!file.startsWith(PUB)) { res.writeHead(403); return res.end('no'); }
  fs.readFile(file, (err, buf) => {
    if (err) { res.writeHead(404, { 'content-type': 'text/plain' }); return res.end('404'); }
    const ext = path.extname(file).toLowerCase();
    res.writeHead(200, {
      'content-type': MIME[ext] || 'application/octet-stream',
      'cache-control': (ext === '.html' || ext === '.js') ? 'no-store' : 'public, max-age=3600'
    });
    res.end(buf);
  });
});

// slowloris on the HTTP side: bound how long a request may dribble in, and how long a
// socket may sit silent before we stop paying for it.
server.headersTimeout = Math.min(20000, HS_IDLE_MS * 2);
server.requestTimeout = 60000;
server.keepAliveTimeout = 10000;
server.maxHeadersCount = 64;
server.on('connection', (socket) => {
  try { socket.setTimeout(HS_IDLE_MS, () => { try { socket.destroy(); } catch (e) {} }); } catch (e) {}
});
server.on('clientError', (err, socket) => {
  try { if (socket.writable && !socket.destroyed) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n'); } catch (e) {}
  try { socket.destroy(); } catch (e) {}
});
server.on('error', (e) => {
  console.log('[fatal] http server error (still serving):', e && (e.stack || e.message));
});

// ---------- websocket ------------------------------------------------------
const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
const clients = new Map();
const connsByIp = new Map();               // address -> Set<socket>: the per-IP connection cap
let nextId = 1;

const OP_TEXT = 0x1, OP_CLOSE = 0x8, OP_PING = 0x9, OP_PONG = 0xA;

/** Token bucket. False means "this frame arrived too fast to be served". */
function admit(c, now) {
  const dt = (now - c.tokenAt) / 1000;
  if (dt > 0) { c.tokens = Math.min(MSG_BURST, c.tokens + dt * MSG_PER_SEC); c.tokenAt = now; }
  if (c.tokens >= 1) { c.tokens -= 1; return true; }
  c.dropped++;
  return false;
}

/** Where a connection really comes from. Behind a tunnel every peer looks local, so a
 *  forwarded-for header is honoured when present and plausible. */
function ipOf(req) {
  const xff = req.headers['x-forwarded-for'];
  if (typeof xff === 'string' && xff) {
    const first = xff.split(',')[0].trim();
    if (first.length && first.length <= 45 && /^[0-9a-fA-F:.\[\]]+$/.test(first)) return first;
  }
  const ip = (req.socket && req.socket.remoteAddress) || 'unknown';
  return ip.startsWith('::ffff:') ? ip.slice(7) : ip;
}

function closeFrame(code, reason) {
  const r = Buffer.from(String(reason || '').slice(0, 60), 'utf8');
  const p = Buffer.alloc(2 + r.length);
  p.writeUInt16BE(code, 0);
  r.copy(p, 2);
  return wsEncode(p, OP_CLOSE);
}

/** Tear one connection down for good: close frame, FIN, then a hard destroy if the peer
 *  will not let go. Never throws — teardown has to work on a half-dead socket too. */
function dropClient(c, why) {
  if (!c || c.gone) return;
  c.gone = true;
  try { console.log(`[net] #${c.id}${c.name ? ' ' + c.name : ''} dropped: ${why} (${live()} online)`); } catch (e) {}
  const s = c.sock;
  try { s.write(closeFrame(why === 'frame too large' ? 1009 : 1008, why)); } catch (e) {}
  try { s.end(); } catch (e) {}
  const t = setTimeout(() => { try { s.destroy(); } catch (e) {} }, 250);
  if (t && t.unref) t.unref();
  clients.delete(s);
}

function wsEncode(str, opcode) {
  const payload = Buffer.from(str, 'utf8');
  const len = payload.length;
  let head;
  if (len < 126) { head = Buffer.alloc(2); head[1] = len; }
  else if (len < 65536) { head = Buffer.alloc(4); head[1] = 126; head.writeUInt16BE(len, 2); }
  else { head = Buffer.alloc(10); head[1] = 127; head.writeBigUInt64BE(BigInt(len), 2); }
  head[0] = 0x80 | (opcode === undefined ? 1 : opcode);
  return Buffer.concat([head, payload]);
}

server.on('upgrade', (req, socket) => {
  const key = req.headers['sec-websocket-key'];
  if (!key || socket.destroyed) { try { socket.destroy(); } catch (e) {} return; }

  // Connection caps come first: a peer that is already over its allowance costs us
  // nothing but a 503, and a socket we never accepted can never become a client.
  const ip = ipOf(req);
  let byIp = connsByIp.get(ip);
  if (!byIp) { byIp = new Set(); connsByIp.set(ip, byIp); }
  if (byIp.size >= MAX_CONN_PER_IP || clients.size >= MAX_CONNS) {
    console.log(`[net] refused ${ip}: ${byIp.size} open from that address (cap ${MAX_CONN_PER_IP}), ${clients.size} total`);
    // end() (not destroy()) so the refusal is actually flushed to the peer
    try { socket.end('HTTP/1.1 503 Service Unavailable\r\nConnection: close\r\nContent-Length: 0\r\n\r\n'); } catch (e) {}
    const t = setTimeout(() => { try { socket.destroy(); } catch (e) {} }, 250);
    if (t && t.unref) t.unref();
    if (!byIp.size) connsByIp.delete(ip);
    return;
  }
  byIp.add(socket);

  socket.write(
    'HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n' +
    'Sec-WebSocket-Accept: ' + crypto.createHash('sha1').update(key + GUID).digest(B64) + '\r\n\r\n'
  );
  socket.setNoDelay(true);
  socket.setTimeout(HS_IDLE_MS);      // silence before hello costs the socket

  const c = {
    id: nextId++, sock: socket, ip, key: null, name: null, hue: 0, map: 0,
    x: 0, y: 0, hp: PLAYER_HP, maxHp: PLAYER_HP, kills: 0, atk: BASE_ATK,
    inv: { wood: 0, ore: 0, herb: 0, crystal: 0, gold: 0 }, tool: 0, atkBoost: 0,
    tokenPending: 0, tokenWallet: null, walletNonce: null, walletNonceAt: 0,
    paletteId: CU.DEFAULT_PALETTE_ID, bodyHue: 0, trimHue: 0, accessories: { hat: null, cloak: null, scarf: null, visor: null, pack: null, patch: null },
    achIds: new Set(), achMaps: new Set(), achCrafts: 0, achTitle: null,
    energy: ENERGY_MAX, subs: new Set(), sent: new Set(),
    // src/anti-cheat.js's rolling state — deliberately in-memory only, never persisted:
    // it's a short-timescale behavioral signal that fully decays within minutes (see that
    // module's header), so a fresh connection starting at zero is correct, not a gap.
    acHistory: [], acScore: 0, acLastAt: null, acWasThrottled: false,
    // Reward-yield bonuses (2026-09-21 round) — all in-memory only, all safe defaults:
    // streakState decays/rebuilds purely from play, holderBalance stays 0 (base 1.0x,
    // see holderBalanceLookup() below) until a real, non-placeholder token mint
    // exists and a balance read actually succeeds.
    streakState: { streak: 0, lastAt: null },
    holderBalance: 0, holderMultiplier: HolderBonus.BASE_MULTIPLIER,
    // Builder-bonus (src/builder-bonus.js): live count of structures this player
    // currently owns, refreshed on hello + whenever build/release changes it (see
    // refreshBuilderBonus() below) — never recomputed on every reward action, unlike
    // the mistake already made and fixed once for anti-cheat's pending aggregates.
    builderCount: 0, builderMultiplier: BuilderBonus.BASE_MULTIPLIER,
    pet: Pets.emptyState(),
    ready: false, lastMove: Date.now(), dead: false,
    gone: false, bad: 0, lastRx: Date.now(), tokenAt: Date.now(), tokens: MSG_BURST, dropped: 0,
    send(obj) {
      if (c.gone || socket.destroyed) return;
      // a peer that stops reading must not be able to grow our memory: drop it instead
      if (socket.writableLength > MAX_OUTBUF) return dropClient(c, 'outbound backlog');
      try { socket.write(wsEncode(JSON.stringify(obj))); } catch (e) {}
    }
  };
  clients.set(socket, c);

  let buf = Buffer.alloc(0);
  socket.on('data', (chunk) => {
    c.lastRx = Date.now();
    try {
      if (c.gone) return;
      if (buf.length + chunk.length > MAX_BUFFER) return dropClient(c, 'buffered bytes');
      buf = buf.length ? Buffer.concat([buf, chunk]) : chunk;
      for (;;) {
        if (c.gone) return;
        if (buf.length < 2) return;
        const b0 = buf[0], b1 = buf[1];
        const op = b0 & 0x0f;
        const masked = (b1 & 0x80) !== 0;
        let len = b1 & 0x7f, off = 2;
        if (len === 126) { if (buf.length < 4) return; len = buf.readUInt16BE(2); off = 4; }
        else if (len === 127) { if (buf.length < 10) return; len = Number(buf.readBigUInt64BE(2)); off = 10; }
        // A frame's size is declared in its header, so it is policed there: a client that
        // announces a huge frame is refused before we buffer a single byte of it.
        if (!Number.isFinite(len) || len < 0 || len > MAX_FRAME) return dropClient(c, 'frame too large');
        let mask = null;
        if (masked) { if (buf.length < off + 4) return; mask = buf.subarray(off, off + 4); off += 4; }
        if (buf.length < off + len) return;
        let payload = Buffer.from(buf.subarray(off, off + len));
        buf = buf.subarray(off + len);
        if (mask) for (let i = 0; i < payload.length; i++) payload[i] ^= mask[i & 3];

        // every frame, including control frames, is billed against the rate limit
        if (!admit(c, Date.now())) {
          if (c.dropped > FLOOD_SLACK) return dropClient(c, 'rate limit exceeded');
          continue;                                  // short burst: frame dropped, socket kept
        }

        if (op === OP_CLOSE) return dropClient(c, 'client close');
        if (op === OP_PING) { try { socket.write(wsEncode(payload.toString('utf8'), OP_PONG)); } catch (e) {} continue; }
        if (op === OP_PONG) continue;
        if (op !== OP_TEXT) continue;                // binary / unknown opcode: consumed, ignored

        let msg;
        try { msg = JSON.parse(payload.toString('utf8')); }
        catch (e) { c.bad++; continue; }             // malformed JSON: ignored, connection kept
        try { onMessage(c, msg); }
        catch (e) { console.log('[err]', e && (e.stack || e.message)); }
      }
    } catch (e) {
      // a decoder fault must never take the process with it
      console.log('[err] frame decode:', e && (e.stack || e.message));
      dropClient(c, 'decode error');
    }
  });
  socket.on('error', () => {});
  // An upgraded socket is half-open by default, so a peer that closes (or dies) shows up
  // as 'end' — never as 'close'. Without this, dead connections would keep their slot in
  // the per-IP ledger and their entry in the client map until an idle sweep caught them.
  socket.on('end', () => dropClient(c, 'peer closed'));
  socket.on('close', () => {
    clients.delete(socket);
    const s = connsByIp.get(ip);
    if (s) { s.delete(socket); if (!s.size) connsByIp.delete(ip); }
    console.log(`[net] ${c.name || '#' + c.id} left (${live()} online)`);
  });
  console.log(`[net] #${c.id} connected`);
});

function live() { return [...clients.values()].filter(c => c.ready).length; }
function ready() { return [...clients.values()].filter(c => c.ready); }
function subKey(map, cx, cy) { return map + ':' + cx + ':' + cy; }

function sendChunk(c, cx, cy) {
  const map = c.map;
  const x0 = cx * CHUNK, y0 = cy * CHUNK;
  const out = []; const owners = []; const oIdx = new Map();
  for (let j = 0; j < CHUNK; j++) {
    for (let i = 0; i < CHUNK; i++) {
      const t = tiles.get(map + ':' + ((y0 + j) * W + (x0 + i)));
      if (!t) continue;
      let oi = oIdx.get(t.owner);
      if (oi === undefined) { oi = owners.length; owners.push(t.owner); oIdx.set(t.owner, oi); }
      out.push(i, j, t.m, oi);
    }
  }
  const bytes = new Uint8Array(out.length);
  for (let i = 0; i < out.length; i++) bytes[i] = out[i] & 0xff;
  c.send({
    t: 'chunk', map, cx, cy, n: out.length / 4,
    d: Buffer.from(bytes).toString(B64), owners,
    nodes: world.nodesForChunk(map, cx, cy),
    drops: world.dropsForChunk(map, cx, cy),
    structures: structuresForChunk(map, cx, cy),
    monuments: monumentsForChunk(map, cx, cy)
  });
}

/** Structures in one chunk, current fill level included — the only per-structure work
 *  that happens outside build/collect (no background tick computes this ahead of time). */
function structuresForChunk(map, cx, cy) {
  const x0 = cx * CHUNK, y0 = cy * CHUNK, now = Date.now();
  const out = [];
  for (const s of structures.values()) {
    if (s.map !== map || s.x < x0 || s.x >= x0 + CHUNK || s.y < y0 || s.y >= y0 + CHUNK) continue;
    const def = Idle.structureOf(s.kind);
    if (!def) continue;
    out.push({ id: s.id, kind: s.kind, x: s.x, y: s.y, owner: s.owner, accrued: Idle.accrued(s, now), capacity: def.capacity, resource: def.produces, blocksMovement: !!def.blocksMovement });
  }
  return out;
}

function setView(c, tx, ty) {
  const ccx = T.chunkOf(tx), ccy = T.chunkOf(ty);
  const want = new Set();
  for (let dy = -VIEW_RADIUS; dy <= VIEW_RADIUS; dy++) {
    for (let dx = -VIEW_RADIUS; dx <= VIEW_RADIUS; dx++) {
      const cx = ccx + dx, cy = ccy + dy;
      if (cx < 0 || cy < 0 || cx * CHUNK >= W || cy * CHUNK >= H) continue;
      want.add(subKey(c.map, cx, cy));
    }
  }
  const fresh = [];
  for (const k of want) {
    if (!c.sent.has(k)) { c.sent.add(k); const p = k.split(':'); fresh.push([+p[1], +p[2]]); }
  }
  // forget subscriptions to other maps
  for (const k of [...c.sent]) if (!k.startsWith(c.map + ':')) c.sent.delete(k);
  c.subs = want;
  for (const f of fresh) sendChunk(c, f[0], f[1]);
}

function broadcastTile(map, cx, cy, x, y, m, owner) {
  const k = subKey(map, cx, cy);
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send({ t: 'tiles', list: [[x, y, m, owner]] });
}

/** A structure was built — tell everyone nearby through the same chunk-subscription
 *  delivery every other placed thing uses (broadcastTile/broadcastDrop). */
function broadcastStructure(map, x, y, struct) {
  const cx = T.chunkOf(x), cy = T.chunkOf(y), k = subKey(map, cx, cy);
  const def = Idle.structureOf(struct.kind);
  if (!def) return;
  const payload = { t: 'structure', map, id: struct.id, kind: struct.kind, x, y, owner: struct.owner, accrued: 0, capacity: def.capacity, resource: def.produces, blocksMovement: !!def.blocksMovement };
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send(payload);
}

/** A structure was removed (owner released it) — tell everyone nearby so it disappears
 *  from their map too, same delivery shape as broadcastDropGone. */
function broadcastStructureGone(map, x, y) {
  const cx = T.chunkOf(x), cy = T.chunkOf(y), k = subKey(map, cx, cy);
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send({ t: 'structure-gone', map, x, y });
}

/** A loot cache appeared (death, or a partial pickup leaving a remainder) — tell everyone nearby. */
function broadcastDrop(map, x, y, drop) {
  const cx = T.chunkOf(x), cy = T.chunkOf(y), k = subKey(map, cx, cy);
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send({ t: 'drop', map, id: drop.id, x, y, res: drop.res, at: drop.at, ttlMs: drop.ttlMs });
}

/** A loot cache is gone (fully looted or expired) — tell everyone nearby to drop it too. */
function broadcastDropGone(map, x, y) {
  const cx = T.chunkOf(x), cy = T.chunkOf(y), k = subKey(map, cx, cy);
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send({ t: 'drop-gone', map, x, y });
}

function gain(c, what, n) { c.inv[what] = (c.inv[what] || 0) + n; }

// Anti-cheat IP-density tracking (src/anti-cheat.js's third, amplifier-only signal): which
// distinct player keys have earned a commerce reward from each IP recently. A soft signal
// by design — shared networks, NAT, campus/office wifi are real and innocent — so this
// feeds a count into AntiCheat.evaluate() and nothing else; see that module's header for
// why IP density alone can never throttle regardless of how long it's sustained.
const IP_EARNER_WINDOW_MS = 120000; // 2 minutes — "recently active", not a tight timing window
const recentEarnersByIp = new Map(); // ip -> Map<key, lastSeenTs>
function ipEarnerCount(ip, key, now) {
  let byKey = recentEarnersByIp.get(ip);
  if (!byKey) { byKey = new Map(); recentEarnersByIp.set(ip, byKey); }
  byKey.set(key, now);
  for (const [k, t] of byKey) if (now - t > IP_EARNER_WINDOW_MS) byKey.delete(k);
  if (byKey.size === 0) recentEarnersByIp.delete(ip);
  return byKey.size;
}

// Ledger-velocity & IP pending concentration (anti-cheat signals 4 & 5) — both
// amplifier-only, same structural guarantee as IP density: alone, forever, they
// contribute nothing, so a legitimate grinder who simply holds more pending than
// average, or shares an IP with other earners, is never throttled purely for that.
// Ledger-velocity tracks pending STRATUM per key per hour in-memory and flags when
// one key's pending exceeds 3× the median pending among active earners. IP
// concentration flags when one IP's players together hold >40% of world-total
// pending. Both fully reversible and decaying: pending is re-read from the DB
// each reward, so the signal collapses as soon as earning pauses.
const ipPendingLogAt = new Map(); // ip -> last log timestamp (rate-limit amplifier logs)
function computeMedianPendingOfActive() {
  var keys = new Set();
  for (const byKey of recentEarnersByIp.values()) for (const k of byKey.keys()) keys.add(k);
  for (const cl of clients.values()) if (cl.ready && cl.key) keys.add(cl.key);
  if (!keys.size) return 0;
  var vals = [];
  for (const k of keys) {
    try { var row = qLedgerGet.get(k); vals.push(row ? (row.pending | 0) : 0); } catch (e) { vals.push(0); }
  }
  return AntiCheat.medianOf(vals);
}
function ipPendingTotal(ip) {
  var byKey = recentEarnersByIp.get(ip);
  if (!byKey || byKey.size === 0) return 0;
  var sum = 0;
  for (const k of byKey.keys()) {
    try { var row = qLedgerGet.get(k); sum += row ? (row.pending | 0) : 0; } catch (e) {}
  }
  return sum;
}
function computeWorldTotalPending() {
  try { var row = qLedgerTotal.get(); return row ? (row.t | 0) : 0; } catch (e) { return 0; }
}
// medianPendingOfActive/worldTotalPending used to run their real query on every single
// reward-earning action (applyCommerceReward() below is the hot path EVERY harvest hit,
// kill, craft and structure-collect passes through) — medianPendingOfActive() alone does
// one synchronous better-sqlite3 read PER active player, so with P concurrently-mining
// players that was O(P) blocking reads per action, O(P^2) per second server-wide, on top
// of worldTotalPending()'s full-table SUM every single time too. better-sqlite3 is
// synchronous: every one of those reads stalls the entire event loop, so this was a real,
// worsening-with-population lag source hit by EVERY connected player on EVERY other
// player's every mining click, not just the acting player's own. Both signals are
// amplifier-only heuristics meant to catch SUSTAINED abuse over tens of seconds to
// minutes (see WEIGHT_LEDGER_VELOCITY's header) — they were never precision-critical to
// the millisecond, so refreshing them on a coarse timer instead of per-action loses
// nothing the design actually needed while turning O(P) reads-per-action into O(P)
// reads-per-4-seconds, regardless of action rate.
const PENDING_AGG_REFRESH_MS = 4000;
let pendingAggCache = { median: 0, total: 0 };
function refreshPendingAggCache() {
  try { pendingAggCache = { median: computeMedianPendingOfActive(), total: computeWorldTotalPending() }; }
  catch (e) {}
}
refreshPendingAggCache(); // seed it at boot instead of starting from all-zero for 4s
var _pendingAggSweep = setInterval(refreshPendingAggCache, PENDING_AGG_REFRESH_MS);
if (_pendingAggSweep && _pendingAggSweep.unref) _pendingAggSweep.unref();

// Wallet-challenge nonce replay protection — single-use, 5-minute TTL, global.
// The per-connection c.walletNonce/c.walletNonceAt already makes a nonce single-use
// within one socket, but without a global store a captured challenge could be replayed
// on a second socket for the same key within its 2-minute freshness window. This
// global registry closes that: every issued nonce is tracked once, checked once, and
// expires automatically. Existing per-connection flow is preserved — this is an
// additional gate, not a replacement, so no break to the current handshake.
const WALLET_NONCE_TTL_MS = 5 * 60 * 1000;
const walletNonces = new Map(); // nonce hex -> expiresAt (ms since epoch)
function pruneWalletNonces(now) {
  for (const [nonce, exp] of walletNonces) if (now >= exp) walletNonces.delete(nonce);
}
function issueWalletNonce(nonce, now) {
  pruneWalletNonces(now);
  walletNonces.set(nonce, now + WALLET_NONCE_TTL_MS);
}
function consumeWalletNonce(nonce, now) {
  pruneWalletNonces(now);
  var exp = walletNonces.get(nonce);
  if (exp === undefined) return false;
  walletNonces.delete(nonce);
  return now < exp;
}
// Periodic sweep for expired nonces so the map never grows if challenges are
// issued but never redeemed (e.g. client disconnects). 60s cadence is cheap
// and keeps expiry honoured even when no link arrives to trigger a prune.
var _walletNonceSweep = setInterval(function () { pruneWalletNonces(Date.now()); }, 60000);
if (_walletNonceSweep && _walletNonceSweep.unref) _walletNonceSweep.unref();

/** floor(amount * mult), never below `amount` — the one combining rule every yield-bonus
 *  module here already promises individually (holder-bonus.js, mining-streak.js,
 *  colony-milestone.js); applying it ONCE to the combined multiplier (instead of chaining
 *  three separate per-module floors) is both simpler and loses less to rounding. */
function boostByMultiplier(amount, mult) {
  const a = (Number.isInteger(amount) && amount >= 0) ? amount : 0;
  if (a === 0) return 0;
  const m = (typeof mult === 'number' && isFinite(mult) && mult > 1) ? mult : 1;
  const boosted = Math.floor(a * m);
  return boosted > a ? boosted : a;
}

/**
 * Dual commerce payout: soft gold into inv + hard token units into token_ledger.
 * Returns the reward applied (or zeros). Never throws.
 *
 * Every call also feeds src/anti-cheat.js's rolling per-player suspicion score (this is
 * the ONE place every reward-earning action passes through, so it's the one place to hook
 * — see that module's header for the full design). A throttled call still returns zeros
 * exactly like a "nothing to reward" call already did; the caller's game action (inventory
 * gain, harvest depletion, craft materials spent, kill XP, ...) is untouched either way —
 * only the ECONOMIC reward is ever suppressed, never the action itself, never a ban, never
 * anything requiring a human to review or undo (ROADMAP.md's no-admins rule, honored).
 *
 * This is ALSO the one place the four yield bonuses compose, on top of the base reward
 * (and any batch `multiplier`, applied first — see that param's own comment):
 *   - src/colony-milestone.js — global, from the server-wide burnedTotal() (everyone gets
 *     the same colony-wide multiplier at any given moment, regardless of action type).
 *   - src/mining-streak.js — personal, harvest-only (mining is this game's primary loop;
 *     see that module's header for why only 'harvest' actions build or break the streak —
 *     crafting/killing/collecting between harvests never touches it either way).
 *   - src/holder-bonus.js — personal, from c.holderMultiplier (refreshed by
 *     refreshHolderBonus() below; always 1.0x until a real, non-placeholder token exists
 *     — see that module's header for why it never guesses at a balance).
 *   - src/builder-bonus.js — personal, from c.builderMultiplier (refreshed by
 *     refreshBuilderBonus() below, on hello/build/release — see that module's header for
 *     why "currently owned" and why its ceiling deliberately matches holder-bonus's).
 * Mining and building are the two things this game is primarily about (mining-streak and
 * builder-bonus), holding is the one thing that can be bought (holder-bonus) instead of
 * played for, and the colony milestone is what everyone gets for spending together — all
 * four multiply into one combined factor, applied once via boostByMultiplier() so
 * rounding is lost at most once, not four times.
 */
function applyCommerceReward(c, action, ctx, multiplier) {
  try {
    // `multiplier` scales the reward for a single request that legitimately represents
    // more than one unit of the action — batch crafting (src/crafting.js), specifically.
    // This is deliberately ONE anti-cheat evaluation below, not `multiplier` of them: the
    // player performed ONE real action (submitting one batch request), and evaluating the
    // rate/rhythm signals `multiplier` times in a synchronous loop would hand them all
    // near-identical timestamps, which is EXACTLY what src/anti-cheat.js's RHYTHM signal
    // is designed to flag — a legitimate batch craft would look machine-regular purely as
    // an artifact of how this function was called, not because of anything the player
    // actually did. One evaluation, scaled reward, is both more honest and immune to that.
    const mult = (typeof multiplier === 'number' && isFinite(multiplier) && multiplier > 0) ? Math.floor(multiplier) : 1;
    let now;
    if (c.key) {
      now = Date.now();
      const ipCount = ipEarnerCount(c.ip, c.key, now);
      // Ledger-velocity & IP concentration aggregates for amplifier signals 4 & 5.
      // All purely in-memory / DB-read, fully reversible and never persisted.
      var pendingAgg = { pending: 0, medianPending: 0, ipPending: 0, totalPending: 0 };
      try {
        var led = ledgerOf(c.key);
        pendingAgg.pending = led.pending | 0;
        // Read from the coarse periodic cache, not a fresh O(active players) scan every
        // action — see refreshPendingAggCache()'s header above for why. ipPendingTotal()
        // stays synchronous-per-action: it's bounded by one IP's own recently-earning
        // keys (a household/office, not the whole server), so it never has this signal's
        // quadratic-with-population blowup.
        pendingAgg.medianPending = pendingAggCache.median;
        pendingAgg.ipPending = ipPendingTotal(c.ip);
        pendingAgg.totalPending = pendingAggCache.total;
        // Keep the optional anti-cheat.js in-memory tracker in sync when the
        // server already knows the aggregates — no extra cost, and it satisfies
        // the "in-memory Map, decays like existing score" brief for callers that
        // prefer to use AntiCheat.trackPending()/medianPending() directly.
        try { AntiCheat.trackPending(c.key, pendingAgg.pending, now); } catch (e) {}
      } catch (e) {}
      const ev = AntiCheat.evaluate({ history: c.acHistory, score: c.acScore, lastAt: c.acLastAt }, now, ipCount, pendingAgg);
      c.acHistory = ev.history; c.acScore = ev.score; c.acLastAt = ev.lastAt;
      // IP pending concentration amplifier logging — rate-limited once per minute per IP
      if (ev.flags.ipPendingConcentration) {
        var last = ipPendingLogAt.get(c.ip) || 0;
        if (now - last > 60000) {
          ipPendingLogAt.set(c.ip, now);
          console.log(`[anti-cheat] IP pending concentration amplifier triggered ip=${c.ip} ` +
            `ipPending=${pendingAgg.ipPending} total=${pendingAgg.totalPending} ` +
            `share=${pendingAgg.totalPending ? (pendingAgg.ipPending / pendingAgg.totalPending).toFixed(2) : '0'} ` +
            `score=${ev.score.toFixed(1)} flags=${JSON.stringify(ev.flags)}`);
        }
      }
      // Also log ledger-velocity amplifier once per minute per IP when it fires (same
      // rate-limit map, but tagged distinctly — sharing the minute bucket is intentional:
      // if either amplifier is chattering, once/minute is enough signal).
      if (ev.flags.ledgerVelocity && !ev.flags.ipPendingConcentration) {
        var lastV = ipPendingLogAt.get('vel:' + c.ip) || 0;
        if (now - lastV > 60000) {
          ipPendingLogAt.set('vel:' + c.ip, now);
          console.log(`[anti-cheat] ledger-velocity amplifier triggered key=${c.key.slice(0, 8)}… ` +
            `pending=${pendingAgg.pending} median=${pendingAgg.medianPending} ` +
            `score=${ev.score.toFixed(1)} flags=${JSON.stringify(ev.flags)}`);
        }
      }
      if (ev.throttled) {
        if (!c.acWasThrottled) {
          console.log(`[anti-cheat] #${c.id}${c.name ? ' ' + c.name : ''} economic reward throttled ` +
            `(score=${ev.score.toFixed(1)} flags=${JSON.stringify(ev.flags)})`);
        }
        c.acWasThrottled = true;
        return { gold: 0, token: 0, tokenPending: c.tokenPending | 0 };
      }
      c.acWasThrottled = false;
    }
    const r = Rewards.rewardFor(action, ctx || {});
    if (!Rewards.hasReward(r)) return { gold: 0, token: 0, tokenPending: c.tokenPending | 0 };
    const baseGold = (r.gold | 0) * mult, baseToken = (r.token | 0) * mult;

    // Mining streak only ever moves for a real harvest, on a real (keyed) player — see
    // the function-level comment above for why crafting/killing/collecting never touch it.
    let streakMult = MiningStreak.BASE_MULTIPLIER;
    if (action === 'harvest' && c.key) {
      const sev = MiningStreak.evaluate(c.streakState, now);
      c.streakState = { streak: sev.streak, lastAt: sev.lastAt };
      streakMult = sev.multiplier;
    }
    const colonyMult = ColonyMilestone.multiplierFor(burnedTotal());
    const holderMult = (typeof c.holderMultiplier === 'number' && c.holderMultiplier >= 1)
      ? c.holderMultiplier : HolderBonus.BASE_MULTIPLIER;
    const builderMult = (typeof c.builderMultiplier === 'number' && c.builderMultiplier >= 1)
      ? c.builderMultiplier : BuilderBonus.BASE_MULTIPLIER;
    // Tithe yield: +10% while any standing order is active. Read live per action
    // (a lapsed/cancelled tithe stops paying immediately) — one indexed row read.
    let titheMult = 1;
    try { if (c.key && titheSettlers(c.key).length > 0) titheMult = Tithes.MULT; } catch (e) {}
    const combinedMult = colonyMult * streakMult * holderMult * builderMult * titheMult;

    const gold = boostByMultiplier(baseGold, combinedMult);
    const token = boostByMultiplier(baseToken, combinedMult);
    const gldx = Gldx.creditFor(action, combinedMult, ctx || {});
    if (gold > 0) gain(c, 'gold', gold);
    if (token > 0 && c.key) c.tokenPending = creditToken(c.key, token);
    if (gldx > 0 && c.key) c.gldxPending = creditGldx(c.key, gldx);
    return {
      gold, token, gldx,
      tokenPending: c.tokenPending | 0,
      gldxPending: c.gldxPending | 0,
      gldxPayable: (c.gldxPayable | 0)
    };
  } catch (e) {
    return { gold: 0, token: 0, tokenPending: c.tokenPending | 0 };
  }
}

/**
 * Best-effort, fire-and-forget refresh of a connection's on-chain STRATUM holder tier
 * (src/holder-bonus.js). Never awaited by its caller — the WS handlers that trigger this
 * (wallet-link, and 'welcome' for a returning player whose wallet was already linked)
 * finish synchronously either way; this just updates c.holderBalance/c.holderMultiplier
 * whenever the read eventually resolves (or leaves them at their prior/base value on any
 * failure — see chain-adapter.js's readBalance(), which is itself always a no-op today:
 * gated behind the same non-placeholder-mint check as real settlement). A successful
 * refresh also pushes a 'holder-tier' message so the HUD can update without a reconnect.
 */
function refreshHolderBonus(c) {
  if (!c || !c.tokenWallet) return;
  ChainAdapter.readBalance(c.tokenWallet, claimEnv()).then((res) => {
    if (c.gone || !res.ok) return; // silent no-op — see the comment above; never surfaced as an error
    c.holderBalance = res.balance;
    c.holderMultiplier = HolderBonus.multiplierFor(res.balance);
    const tier = HolderBonus.tierFor(res.balance);
    c.send({ t: 'holder-tier', balance: res.balance, multiplier: c.holderMultiplier, tier: tier.name });
  }).catch(() => {}); // readBalance() itself never rejects, but this is the one async
  // fire-and-forget call in the whole codebase not awaited by a caller — defend anyway.
}

/**
 * Synchronous refresh of a connection's builder tier (src/builder-bonus.js) — unlike
 * refreshHolderBonus() above, this is a local indexed SQLite read, not a network call,
 * so there is nothing to await asynchronously. Called on hello (a returning player's
 * standing colony) and after any successful build-structure/release-structure (the only
 * two actions that can change what this player owns) — deliberately NOT from
 * applyCommerceReward()'s hot path, which is exactly the per-action DB-read mistake this
 * project already made once for anti-cheat's pending aggregates and fixed by caching.
 * A structure count is comparatively rare to change (a build/release, not a mine click),
 * so refreshing it exactly when it changes is both correct and cheap — no cache needed.
 */
function refreshBuilderBonus(c) {
  if (!c || !c.key) return;
  try {
    const row = qStructCount.get(c.key);
    const count = row ? (row.n | 0) : 0;
    c.builderCount = count;
    c.builderMultiplier = BuilderBonus.multiplierFor(count);
    const tier = BuilderBonus.tierFor(count);
    c.send({ t: 'builder-tier', count, multiplier: c.builderMultiplier, tier: tier.name });
  } catch (e) {} // never let a bonus refresh take the connection down
}

/** Best owned bonus of a gear kind: weapons add damage, armour soaks it. Zero when bare. */
function gearBonus(inv, kind) {
  let best = 0;
  if (!inv || typeof inv !== 'object') return 0;
  for (const k of Object.keys(inv)) {
    if (!inv[k]) continue;
    const it = ECO.itemOf(k);
    if (!it || it.kind !== kind) continue;
    if (kind === 'weapon') best = Math.max(best, it.damageBonus | 0);
    else best = Math.max(best, it.mitigation | 0);
  }
  return best;
}
function stateSave(c) {
  qState.run(c.key, c.map, Math.round(c.x), Math.round(c.y), Math.round(c.hp), c.kills, JSON.stringify(c.inv), c.tool | 0);
}

function parsePetOwned(raw) {
  let owned = {};
  try { owned = JSON.parse(raw || '{}'); } catch (e) { owned = {}; }
  const out = {};
  if (Array.isArray(owned)) {
    for (const id of owned) if (Pets.petOf(id)) out[id] = true;
  } else if (owned && typeof owned === 'object') {
    for (const k of Object.keys(owned)) if (owned[k] && Pets.petOf(k)) out[k] = true;
  }
  return out;
}
function loadPet(c) {
  const row = qPetGet.get(c.key);
  if (!row) { c.pet = Pets.emptyState(); return; }
  const owned = parsePetOwned(row.owned);
  const out = Pets.petOf(row.out) && owned[row.out] ? row.out : (Pets.petOf(row.out) ? row.out : null);
  c.pet = { out, lastTreatAt: row.lastTreatAt | 0, owned };
}
function savePet(c) {
  if (!c || !c.key) return;
  const st = c.pet || Pets.emptyState();
  qPet.run(c.key, st.out || null, st.lastTreatAt | 0, JSON.stringify(st.owned || {}), Date.now());
}
function ownedList(st) {
  const owned = (st && st.owned) || {};
  return Object.keys(owned).filter(k => owned[k] && Pets.petOf(k));
}
function petSnap(c) {
  const now = Date.now();
  const st = c.pet || Pets.emptyState();
  const active = Pets.isActive(st, now);
  const outPet = Pets.petOf(st.out);
  const owned = ownedList(st);
  const show = outPet || (owned[0] ? Pets.petOf(owned[0]) : null);
  return {
    out: st.out || null,
    owned,
    active,
    name: show ? show.name : '',
    form: show ? show.form : 'wisp',
    pal: show ? show.pal : null,
    job: (active && outPet) ? outPet.job : '',
    treatLeftMs: Pets.treatLeftMs(st, now),
    id: st.out || null
  };
}
function petWire(c) {
  const now = Date.now();
  if (!Pets.isActive(c.pet, now)) return null;
  const p = Pets.petOf(c.pet.out);
  if (!p) return null;
  return [c.key, p.id, Math.round(c.x * 10) / 10, Math.round(c.y * 10) / 10, p.form, p.pal];
}
function nearPetSpecies(c, kind) {
  if (!c || !kind) return null;
  const reach = Pets.TAME_REACH;
  for (const m of world.monsters.values()) {
    if (m.map !== c.map || m.state === 0 || !m.sp) continue;
    if (m.sp.kind !== kind) continue;
    const dx = m.x - c.x, dy = m.y - c.y;
    if (dx * dx + dy * dy <= reach * reach) return m.sp.kind;
  }
  return null;
}
function sendPet(c, extra) {
  const msg = Object.assign({ t: 'pet', pet: petSnap(c), inv: c.inv, tokenPending: c.tokenPending | 0 }, extra || {});
  if (msg.ok === undefined) msg.ok = !msg.err;
  c.send(msg);
}
function stackLimitsFor(c) {
  const extra = Pets.carryExtra(c.pet, Date.now());
  if (!extra) return ECO.STACK_LIMITS;
  return {
    wood: ECO.STACK_LIMITS.wood + extra,
    ore: ECO.STACK_LIMITS.ore + extra,
    herb: ECO.STACK_LIMITS.herb + extra,
    crystal: ECO.STACK_LIMITS.crystal + extra,
    gold: ECO.STACK_LIMITS.gold
  };
}

// ---------- achievements ----------------------------------------------------
function achSave(c) {
  qAch.run(c.key, JSON.stringify([...c.achIds]), JSON.stringify([...c.achMaps]), c.achCrafts | 0, c.achTitle || null);
}
/** Current per-player stats snapshot achievements.js's predicates run against. */
function achStats(c) {
  return {
    kills: c.kills | 0,
    level: world.hunter(c).level,
    claimed: qClaimCount.get(c.map, c.key).n,
    crafts: c.achCrafts | 0,
    tools: c.tool | 0,
    maps: c.achMaps.size
  };
}
/** Re-evaluate achievements against current stats and unlock anything newly earned:
 *  persist it, tell the client, and surface the newest title as "current". */
function checkAchievements(c) {
  if (!c.ready || !c.key) return;
  const stats = achStats(c);
  const gained = ACH.evaluate([...c.achIds], stats);
  if (!gained.length) return;
  for (const id of gained) {
    c.achIds.add(id);
    const a = ACH.achievementById(id);
    if (!a) continue;
    const title = ACH.titleFor(id);
    if (title) c.achTitle = title;                 // a player can hold many; the newest shows
    c.send({ t: 'achievement', id: a.id, name: a.name, desc: a.desc, title: title || null });
  }
  achSave(c);
}
function sendVitals(c, extra) {
  const o = {
    t: 'vitals', hp: Math.round(c.hp), maxHp: c.maxHp, inv: c.inv, kills: c.kills, atk: c.atk,
    tool: c.tool | 0, level: world.hunter(c).level,
    gold: (c.inv && c.inv.gold) | 0,
    tokenPending: c.tokenPending | 0,
    pet: petSnap(c)
  };
  if (extra) Object.assign(o, extra);
  c.send(o);
}

/**
 * Light grouping (ROADMAP_COZY.md §5): every OTHER ready, living player within
 * GROUP_RADIUS of (x,y) on `actor`'s map gets a SHARE of the XP `actor` just earned —
 * XP only, never materials or loot, which stays with the actor who landed the harvest
 * or the killing blow (simpler, and avoids duplicating scarce resources for free).
 * This is one server-side event fanning credit out to whoever happens to be nearby —
 * bystanders never send a message and never trigger their own award, so there is no
 * way for two clients to each claim credit for the same event.
 */
function creditNearby(actor, x, y, shareXp) {
  const amt = Math.max(0, Math.round(shareXp));
  if (amt <= 0) return;
  for (const o of ready()) {
    if (o === actor || o.map !== actor.map || o.dead) continue;
    const dx = o.x - x, dy = o.y - y;
    if (dx * dx + dy * dy > GROUP_RADIUS * GROUP_RADIUS) continue;
    world.awardXp(o, amt);
    sendVitals(o);              // reuses the existing vitals shape: client already knows how to react to a level-up
  }
}

// ---------- inbound validation ---------------------------------------------
// One rule for every field a client controls: a value that is not a finite number is
// refused outright (NaN, Infinity, null and "12" are not coordinates), and a finite one
// is clamped into the world before it is allowed anywhere near game state.
const isFin = (v) => typeof v === 'number' && Number.isFinite(v);
function clampInt(v, lo, hi, dflt) {
  if (!isFin(v)) return dflt;
  return Math.max(lo, Math.min(hi, Math.trunc(v)));
}
/** Finite coordinate clamped into [0, n-1], or null when it was not a number at all. */
function clampCoord(v, n) {
  if (!isFin(v)) return null;
  return Math.max(0, Math.min(n - 1, Math.trunc(v)));
}
/** Finite coordinate that must already lie inside [0, n-1]; null otherwise. */
function inBounds(v, n) {
  if (!isFin(v)) return null;
  const i = Math.trunc(v);
  return (i < 0 || i >= n) ? null : i;
}
/** Untrusted text -> bounded, printable, control-character-free string. */
function cleanText(v, max) {
  if (isFin(v)) v = String(v);
  if (typeof v !== 'string') return '';
  return v.replace(/[\x00-\x1f\x7f]/g, '').trim().slice(0, max);
}

// ---------- messages -------------------------------------------------------
// The complete set of things a client may say. Anything else is ignored on sight: the
// server never dispatches a type it does not know, so a new type cannot reach any code
// path by accident.
const INBOUND = new Set(['hello', 'move', 'view', 'set', 'release', 'harvest', 'attack', 'travel', 'map', 'ping', 'craft', 'toolup', 'pickup',
  'build-structure', 'collect-structure', 'structure-rush', 'release-structure', 'set-look',
  'shop-list', 'shop-buy', 'shop-cancel', 'trade-offer', 'trade-accept', 'trade-cancel', 'emote',
  'parcel-mint', 'parcel-list', 'parcel-buy', 'parcel-cancel', 'parcel-browse', 'parcel-mine',
  'wallet-link', 'wallet-challenge', 'claim', 'claim-gldx', 'convert', 'buy-vanity',
  'refill-will', 'tithe-start', 'tithe-cancel', 'vault-deposit', 'vault-withdraw',
  'requisition', 'salvage', 'tame', 'pet-treat', 'pet-park', 'pet-out', 'buy-pet', 'discover', 'monument-build']);

function onMessage(c, msg) {
  if (!msg || typeof msg !== 'object' || Array.isArray(msg)) { c.bad++; return; }
  if (typeof msg.t !== 'string' || !INBOUND.has(msg.t)) { c.bad++; return; }
  switch (msg.t) {
    case 'hello': {
      const key = (typeof msg.key === 'string') ? msg.key.slice(0, 64)
        : (isFin(msg.key) ? String(msg.key).slice(0, 64) : '');
      // Never drop this silently: a client that fails here looks identical to a dead
      // socket ("connected" but permanently blank), which is a miserable thing to debug.
      if (!key) return c.send({ t: 'err', err: 'handshake rejected: no key' });
      if (!KEY_RE.test(key)) return c.send({ t: 'err', err: 'handshake rejected: bad key' });
      const name = cleanText(msg.name, 18) || 'WANDERER';
      const prev = qPlayGet.get(key);
      const hue = prev ? prev.hue : (T.hash2(key.length, key.charCodeAt(0) | 0, 7) % 360);

      c.key = key; c.name = name; c.hue = hue; c.ready = true;
      try { c.sock.setTimeout(0); } catch (e) {}   // idle handling now runs on pings + the sweep

      const st = qStateGet.get(key);
      if (st) {
        c.map = st.map; c.x = st.x; c.y = st.y;
        c.hp = Math.max(1, st.hp); c.kills = st.kills;
        try { c.inv = Object.assign({ wood: 0, ore: 0, herb: 0, crystal: 0, gold: 0 }, JSON.parse(st.inv)); } catch (e) {}
        if (!Number.isFinite(c.inv.gold)) c.inv.gold = 0;
        c.tool = (st && Number.isFinite(+st.tool)) ? Math.max(0, Math.min(ECO.maxToolTier(), (+st.tool) | 0)) : 0;
      } else {
        const sp = T.spawnPoint(0);
        c.map = 0; c.x = sp.x; c.y = sp.y;
        // new arrivals wash up with salvaged materials: enough for a first shelter,
        // never enough to skip the harvest loop.
        c.inv = { wood: 6, ore: 4, herb: 2, crystal: 1, gold: 0 };
        c.tool = 0;
      }
      c.atk = BASE_ATK + Math.floor(c.kills / 3);
      c.atkBoost = gearBonus(c.inv, 'weapon');
      c.energy = ENERGY_MAX;

      const ast = qAchGet.get(key);
      if (ast) {
        try { c.achIds = new Set(JSON.parse(ast.ids)); } catch (e) { c.achIds = new Set(); }
        try { c.achMaps = new Set(JSON.parse(ast.maps)); } catch (e) { c.achMaps = new Set(); }
        c.achCrafts = ast.crafts | 0;
        c.achTitle = ast.title || null;
      } else {
        c.achIds = new Set(); c.achMaps = new Set(); c.achCrafts = 0; c.achTitle = null;
      }
      c.achMaps.add(c.map);                          // arriving anywhere counts as visiting it

      const led = ledgerOf(key);
      c.tokenPending = led.pending | 0;
      c.tokenWallet = led.wallet || null;
      c.gldxPending = led.gldxPending | 0;
      c.gldxPayable = led.gldxPayable | 0;
      if (!c.inv || typeof c.inv.gold !== 'number') c.inv.gold = (c.inv && c.inv.gold) | 0;

      // appearance: a returning player's saved look, re-validated against their current
      // unlocks (never trust even our own stored row blindly — an achievement table
      // change should not leave a player wearing something they no longer qualify for).
      // A brand-new (or pre-customization) player keeps their existing hash-derived hue
      // as a STARTING palette pick, reindexed into the palette table, so nobody's
      // identity jarringly changes the day this feature ships.
      let requestedLook;
      if (prev && prev.paletteId) {
        let savedAcc = {};
        try { const parsed = JSON.parse(prev.accessories || '{}'); if (parsed && typeof parsed === 'object') savedAcc = parsed; } catch (e) {}
        requestedLook = Object.assign({ paletteId: prev.paletteId }, savedAcc);
      } else {
        const startIdx = hue % CU.ALL_PALETTES.length;
        requestedLook = { paletteId: CU.ALL_PALETTES[startIdx].id };
      }
      const look = CU.validateLook(requestedLook, [...c.achIds], vanityOwned(key));
      c.accessories = { hat: look.hat, cloak: look.cloak, scarf: look.scarf, visor: look.visor, pack: look.pack, patch: look.patch };
      const pal = CU.paletteOf(look.paletteId) || CU.paletteOf(CU.DEFAULT_PALETTE_ID);
      c.paletteId = pal.id; c.bodyHue = pal.bodyHue; c.trimHue = pal.trimHue;
      loadPet(c);

      const now = Date.now();
      qPlay.run(key, name, hue, prev ? now : now, now, c.paletteId, c.bodyHue, c.trimHue, JSON.stringify(c.accessories));
      refreshBuilderBonus(c); // synchronous (local index read) — fresh before the welcome payload below

      c.send({
        t: 'welcome', id: c.id, key, name, hue, map: c.map, x: c.x, y: c.y,
        hp: Math.round(c.hp), maxHp: c.maxHp, atk: c.atk, inv: c.inv, kills: c.kills,
        tool: c.tool | 0, level: world.hunter(c).level,
        catalog: {
          costs: ECO.MATERIAL_COSTS.map(co => Object.assign({}, co)),
          names: ECO.MATERIAL_NAMES.slice(),
          recipes: ECO.RECIPES.map(r => ({ id: r.id, tier: r.tier, inputs: Object.assign({}, r.inputs), output: { item: r.output.item, count: r.output.count } })),
          items: Object.assign({}, ECO.ITEMS),
          tools: ECO.TOOL_TIERS.map(t => ({ tier: t.tier, id: t.id, name: t.name, cost: Object.assign({}, t.cost) })),
          structures: Object.keys(Idle.STRUCTURES).map(k => {
            const d = Idle.STRUCTURES[k];
            return {
              id: d.id, name: d.name, tier: d.tier, cost: Object.assign({}, d.cost),
              produces: d.produces, ratePerMs: d.ratePerMs, capacity: d.capacity,
              blocksMovement: !!d.blocksMovement
            };
          })
        },
        world: { w: W, h: H, chunk: CHUNK },
        maps: T.MAPS.map(m => ({ id: m.id, name: m.name, tier: m.tier, desc: m.desc })),
        spawn: T.spawnPoint(c.map),
        energy: c.energy, energyMax: ENERGY_MAX, reach: REACH, attackRange: ATTACK_RANGE,
        claimed: countClaims(c.map), total: W * H, online: live(), mapGrid: MAPGRID,
        look: { paletteId: c.paletteId, bodyHue: c.bodyHue, trimHue: c.trimHue,
          hat: c.accessories.hat, cloak: c.accessories.cloak, scarf: c.accessories.scarf,
          visor: c.accessories.visor, pack: c.accessories.pack, patch: c.accessories.patch },
        customization: {
          palettes: CU.ALL_PALETTES.map(p => ({ id: p.id, name: p.name, bodyHue: p.bodyHue, trimHue: p.trimHue })),
          accessories: CU.ALL_ACCESSORIES.map(a => {
            const req = a.unlockedBy ? ACH.achievementById(a.unlockedBy) : null;
            return { id: a.id, name: a.name, slot: a.slot, unlockedBy: a.unlockedBy || null, unlockDesc: req ? req.desc : null,
              priceStratum: CU.vanityPrice(a.id), owned: CU.isVanity(a.id) ? vanityOwned(key).indexOf(a.id) >= 0 : undefined };
          })
        },
        commerce: TokenConfig.publicConfig(COMMERCE),
        gold: (c.inv.gold | 0),
        tokenPending: c.tokenPending | 0,
        tokenWallet: c.tokenWallet || null,
        tithes: titheSettlers(key),
        found: foundSites(key),
        vault: vaultBalance(key),
        gldxMint: Gldx.GLDX_MINT,
        gldxPending: c.gldxPending | 0,
        gldxPayable: c.gldxPayable | 0,
        gldxText: Gldx.format(c.gldxPending | 0),
        gldxReadyText: Gldx.format(c.gldxPayable | 0),
        payout: payoutPublic(),
        colonyQuota: burnedTotal(),
        // Reward-yield bonuses — see applyCommerceReward()'s header for how all four
        // compose. holderBalance/holderMultiplier are whatever was last successfully
        // refreshed (0 / base 1.0x for a brand-new connection — refreshed below,
        // fire-and-forget, if a wallet is already linked); builderCount/builderMultiplier
        // were just freshly recomputed above (a synchronous local read, no fire-and-forget
        // needed); miningStreak is always 0 fresh off a reconnect (the streak is
        // intentionally session-only, see src/mining-streak.js); colonyMilestone is the
        // current global tier, same for every player right now.
        holderBalance: c.holderBalance | 0,
        holderMultiplier: c.holderMultiplier,
        holderTier: HolderBonus.tierFor(c.holderBalance).name,
        builderCount: c.builderCount | 0,
        builderMultiplier: c.builderMultiplier,
        builderTier: BuilderBonus.tierFor(c.builderCount).name,
        miningStreak: c.streakState.streak | 0,
        miningStreakMultiplier: MiningStreak.multiplierForStreak(c.streakState.streak | 0),
        colonyMilestone: ColonyMilestone.milestoneFor(burnedTotal()).name,
        colonyMultiplier: ColonyMilestone.multiplierFor(burnedTotal()),
        pet: petSnap(c)
      });
      refreshHolderBonus(c); // fire-and-forget — no-op if no wallet is linked yet
      // returning players get their unlocked state without a round-trip; a fresh
      // arrival's stats (e.g. having now "visited" their spawn map) are checked right after.
      c.send({ t: 'achievements', unlocked: [...c.achIds], title: c.achTitle });
      setView(c, c.x, c.y);
      world.activate(c.map, c.x, c.y);
      checkAchievements(c);
      console.log(`[net] ${name} joined map ${c.map} at ${Math.round(c.x)},${Math.round(c.y)} (${live()} online)`);
      break;
    }

    case 'view': {
      if (!c.ready) return;
      const vx = clampCoord(msg.x, W), vy = clampCoord(msg.y, H);
      if (vx === null || vy === null) return;          // not a number: refused
      setView(c, vx, vy);
      world.activate(c.map, vx, vy);
      break;
    }

    case 'move': {
      if (!c.ready || c.dead) return;
      const mx = clampCoord(msg.x, W), my = clampCoord(msg.y, H);
      // NaN / Infinity / missing / null: the player does not move at all. (It used to
      // fall through a `| 0` and quietly teleport them to the origin.)
      if (mx === null || my === null) return;
      const now = Date.now();
      const dt = Math.min(1, Math.max(0, now - c.lastMove) / 1000);
      c.lastMove = now;
      const maxStep = dt * 14 + 2;                       // ~14 tiles/s + latency slack
      const dx = mx - c.x, dy = my - c.y;
      // Anti-cheat: a walled tile is a physical obstacle, so the authoritative server
      // must refuse to move a player onto it — never just trust the client's own
      // collision check, which is prediction only (see public/game.js's mirror of this).
      const blockedByWall = structures.get(structKey(c.map, mx, my));
      if (dx * dx + dy * dy <= maxStep * maxStep && !(blockedByWall && Idle.blocksMovement(blockedByWall.kind))) {
        c.x = mx; c.y = my;
      }
      setView(c, c.x, c.y);
      break;
    }

    case 'travel': {
      if (!c.ready) return;
      const id = clampInt(msg.map, 0, 1024, -1);
      const def = T.MAPS.find(m => m.id === id);
      if (!def) return c.send({ t: 'deny2', r: 'no such map' });
      c.map = id;
      const sp = T.spawnPoint(id);
      c.x = sp.x; c.y = sp.y;
      c.sent.clear(); c.subs = new Set();
      c.send({
        t: 'arrived', map: id, name: def.name, desc: def.desc, spawn: sp, x: c.x, y: c.y,
        claimed: countClaims(id), total: W * H, maps: T.MAPS.map(m => ({ id: m.id, name: m.name, tier: m.tier, desc: m.desc }))
      });
      setView(c, c.x, c.y);
      world.activate(id, c.x, c.y);
      c.achMaps.add(id);
      stateSave(c);
      checkAchievements(c);
      console.log(`[net] ${c.name} travelled to #${id} ${def.name}`);
      break;
    }

    // 'release' is the named form of set-with-material-0: same wire shape, same handler,
    // it just hands the tile back to the commons.
    case 'set':
    case 'release': {
      if (!c.ready || c.dead) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) {
        return c.send({ t: 'deny', x: clampInt(msg.x, 0, W - 1, 0), y: clampInt(msg.y, 0, H - 1, 0), r: 'bounds' });
      }
      const m = (msg.t === 'release') ? 0 : clampInt(msg.m, 0, 4095, -1);
      if (m < 0) return c.send({ t: 'deny', x, y, r: 'material' });
      const dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'deny', x, y, r: 'reach' });
      const key = c.map + ':' + (y * W + x);
      const cur = tiles.get(key);
      if (cur && cur.owner !== c.key) return c.send({ t: 'deny', x, y, r: 'owned' });
      const b0 = T.baseTypeFor(c.map, x, y);
      if (m === 0 && b0 === T.ID.VOID) return c.send({ t: 'deny', x, y, r: 'bounds' });

      const isRelease = (m === 0);
      if (!isRelease && !T.isPlaceable(m)) return c.send({ t: 'deny', x, y, r: 'material' });
      if (c.energy < (isRelease ? RELEASE_COST : COST)) return c.send({ t: 'deny', x, y, r: 'energy' });
      // placing a tile spends harvested resources on top of will. The check and the
      // deduction both happen inside this one synchronous handler, so nothing can
      // slip between them.
      if (!isRelease) {
        const cost = ECO.costOfTile(m);
        if (cost && !ECO.canAfford(c.inv, cost)) {
          return c.send({ t: 'deny', x, y, r: 'resources', need: cost, missing: ECO.missingFor(c.inv, cost) });
        }
      }

      const cx = T.chunkOf(x), cy = T.chunkOf(y);
      if (isRelease) {
        if (!cur) return;
        tiles.delete(key);
        qDel.run(c.map, x, y);
        const d = densFor(c.map), i = (((y / MAPSTEP) | 0) * MAPGRID) + ((x / MAPSTEP) | 0);
        if (d[i] > 0) d[i]--;
        bumpClaim(c.map, -1);
        bumpOwner(c.key, -1);
        broadcastTile(c.map, cx, cy, x, y, -1, '');
        c.send({ t: 'unclaim', x, y, claimed: countClaims(c.map) });
      } else {
        tiles.set(key, { m, owner: c.key, map: c.map, x, y });
        qTile.run(c.map, x, y, m, c.key, Date.now());
        if (!cur) {
          const d = densFor(c.map), i = (((y / MAPSTEP) | 0) * MAPGRID) + ((x / MAPSTEP) | 0);
          if (d[i] < 255) d[i]++;
          bumpClaim(c.map, 1);
          bumpOwner(c.key, 1);
        }
        broadcastTile(c.map, cx, cy, x, y, m, c.key);
        c.energy -= COST;
        const pcost = ECO.costOfTile(m);
        if (pcost) { const paid = ECO.applyCost(c.inv, pcost); if (paid) c.inv = paid; }
        stateSave(c);
        c.send({ t: 'you', x, y, m, claimed: countClaims(c.map), energy: c.energy, inv: c.inv });
        if (!cur) checkAchievements(c);        // only a NEW claim can move the claimed-count needle
      }
      break;
    }

    case 'harvest': {
      if (!c.ready || c.dead) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return;      // not a coordinate: never answered as if it were
      const dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'harvested', x, y, err: 'out of reach' });
      const r = world.harvest(c, x, y);
      if (r.err) return c.send({ t: 'harvested', x, y, err: r.err, wait: r.wait });
      if (r.yielded) {
        // better tools pay off more; a tool never pays off LESS than bare hands.
        const boosted = ECO.toolHarvestAmount(c.tool | 0, r.kind);
        const amount = ((typeof boosted === 'number') ? Math.max(r.amount, boosted) : r.amount)
          + Pets.harvestBonus(c.pet, r.kind, Date.now());
        gain(c, r.yields, amount);
        const pay = applyCommerceReward(c, 'harvest', { kind: r.kind });
        world.awardXp(c, HARVEST_XP);      // gathering is a real XP source now (ROADMAP_COZY §3)
        stateSave(c);
        sendVitals(c);                     // same pattern 'craft' uses: level/xp reach the client via vitals
        const ripeSec = Math.ceil((r.ripe - Date.now()) / 1000);
        broadcastNode(c.map, x, y, r.kind, 0, ripeSec);
        const gains = { [r.yields]: amount };
        if (pay.gold) gains.gold = pay.gold;
        if (pay.token) gains.token = pay.token;
        c.send({
          t: 'harvested', x, y, kind: r.kind, state: 0, ripeSec, gains, inv: c.inv,
          tokenPending: c.tokenPending | 0, gldx: pay.gldx | 0,
          gldxPending: c.gldxPending | 0, gldxPayable: c.gldxPayable | 0,
          gldxText: Gldx.format(c.gldxPending | 0), gldxReadyText: Gldx.format(c.gldxPayable | 0),
          streak: c.streakState.streak | 0,
          streakMultiplier: MiningStreak.multiplierForStreak(c.streakState.streak | 0)
        });
        creditNearby(c, x, y, HARVEST_XP * GROUP_XP_SHARE);   // light grouping (ROADMAP_COZY §5)
      } else {
        c.send({ t: 'harvested', x, y, kind: r.kind, state: 1, partial: true, inv: c.inv });
      }
      break;
    }

    case 'pickup': {
      if (!c.ready || c.dead) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return;      // not a coordinate: never answered as if it were
      const dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'pickup', x, y, err: 'out of reach' });
      const r = world.pickupDrop(c.map, x, y, c.inv, Date.now(), stackLimitsFor(c));
      if (!r.ok) return c.send({ t: 'pickup', x, y, err: r.reason || 'none' });
      c.inv = r.inv;
      stateSave(c);
      const rest = world.dropAt(c.map, x, y);
      if (rest) broadcastDrop(c.map, x, y, rest);       // a remainder stayed behind (stack limits)
      else broadcastDropGone(c.map, x, y);
      c.send({ t: 'pickup', x, y, taken: r.taken, left: r.left, inv: c.inv });
      break;
    }

    case 'attack': {
      if (!c.ready || c.dead) return;
      const mid = clampInt(msg.id, 0, 0x7fffffff, -1);
      if (mid < 0) return c.send({ t: 'combat', err: 'no such creature', id: 0 });
      // Sanctuary maps have no click-to-attack: proximity alone resolves ambient ticks
      // (world.js's tick() -> ambientTick), so a swing here is a no-op, not a fight.
      if (T.toneOf(c.map) === 'sanctuary') return c.send({ t: 'combat', err: 'ambient combat here — no need to strike', id: mid });
      c.atkBoost = gearBonus(c.inv, 'weapon');
      const r = world.attack(c, mid);
      if (r.err) return c.send({ t: 'combat', err: r.err, id: mid });
      if (r.killed) {
        c.kills += 1;
        c.atk = BASE_ATK + Math.floor(c.kills / 3);
        gain(c, r.loot, 1);
        const pay = applyCommerceReward(c, 'kill', { xp: r.xp | 0, loot: r.loot });
        stateSave(c);
        c.send({
          t: 'combat', id: r.id, killed: true, name: r.name, loot: r.loot,
          kills: c.kills, atk: c.atk, inv: c.inv, level: world.hunter(c).level,
          gains: { gold: pay.gold, token: pay.token }, tokenPending: c.tokenPending | 0,
          gldx: pay.gldx | 0, gldxPending: c.gldxPending | 0, gldxPayable: c.gldxPayable | 0,
          gldxText: Gldx.format(c.gldxPending | 0), gldxReadyText: Gldx.format(c.gldxPayable | 0)
        });
        checkAchievements(c);                  // kills track AND level (XP is only awarded here)
        creditNearby(c, r.x, r.y, r.xp * GROUP_XP_SHARE);   // light grouping (ROADMAP_COZY §5): XP only, loot stays with the killer
      } else {
        c.send({ t: 'combat', id: r.id, killed: false, name: r.name, hp: r.hp, maxHp: r.maxHp });
      }
      break;
    }

    case 'craft': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 32);
      const rec = ECO.recipeById(id);
      if (!rec) return c.send({ t: 'crafted', err: 'unknown recipe', id });
      if (rec.tier > (c.tool | 0)) return c.send({ t: 'crafted', err: 'locked: needs ' + (ECO.toolTier(rec.tier) || {}).name + ' tools', id });

      // Batch (src/crafting.js): an omitted count behaves exactly as a single craft
      // always has — same message shape, same response — so msg.count only changes
      // anything when it's a real request for more than one.
      const cv = Crafting.validateBatchCount(msg.count === undefined ? 1 : msg.count);
      if (!cv.ok) return c.send({ t: 'crafted', err: cv.error, id });
      const batchCount = cv.count;

      let item, count;
      if (batchCount === 1) {
        const res = ECO.craft(id, c.inv);
        if (!res.ok) return c.send({ t: 'crafted', err: res.error, id });
        c.inv = res.inv;
        item = res.item; count = res.count;
      } else {
        const scaledCost = Crafting.batchCost(rec.inputs, batchCount);
        if (!scaledCost || !ECO.canAfford(c.inv, scaledCost)) {
          const miss = scaledCost ? ECO.missingFor(c.inv, scaledCost) : {};
          const parts = []; for (const m in miss) parts.push(m + ' ' + miss[m]);
          return c.send({ t: 'crafted', err: 'insufficient resources: ' + parts.join(', '), id });
        }
        const outCount = Crafting.batchOutputCount(rec.output.count, batchCount);
        const paidInv = ECO.applyCost(c.inv, scaledCost);
        if (!paidInv || ECO.roomFor(paidInv, rec.output.item) < outCount) {
          return c.send({ t: 'crafted', err: 'stack limit reached for ' + rec.output.item, id });
        }
        c.inv = ECO.add(paidInv, rec.output.item, outCount);
        item = rec.output.item; count = outCount;
      }

      c.atkBoost = gearBonus(c.inv, 'weapon');
      c.achCrafts = (c.achCrafts | 0) + batchCount;
      // One commerce-reward call, scaled by batchCount — see applyCommerceReward()'s own
      // comment for why this is ONE anti-cheat evaluation with a scaled payout, not
      // batchCount separate ones.
      const pay = applyCommerceReward(c, 'craft', { tier: rec.tier | 0 }, batchCount);
      world.awardXp(c, (CRAFT_XP_BASE + CRAFT_XP_PER_TIER * rec.tier) * batchCount);  // crafting is a real XP source now (ROADMAP_COZY §3)
      stateSave(c);
      sendVitals(c);
      c.send({
        t: 'crafted', id, item, count, inv: c.inv, atkBoost: c.atkBoost,
        gains: { gold: pay.gold, token: pay.token }, tokenPending: c.tokenPending | 0,
        gldx: pay.gldx | 0, gldxPending: c.gldxPending | 0, gldxPayable: c.gldxPayable | 0,
        gldxText: Gldx.format(c.gldxPending | 0), gldxReadyText: Gldx.format(c.gldxPayable | 0)
      });
      checkAchievements(c);
      break;
    }

    // Salvage (src/crafting.js): break down `count` held crafted items back into a partial
    // materials refund (SALVAGE_REFUND_BPS, default 50%). Deliberately no commerce reward
    // here — this reverses a purchase, it doesn't earn a new one — and deliberately no
    // anti-cheat evaluation either: salvaging never grants gold or STRATUM, so it isn't a
    // reward-earning action anti-cheat needs to watch (see applyCommerceReward()'s header).
    case 'salvage': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 32);
      const rec = ECO.recipeById(id);
      if (!rec) return c.send({ t: 'salvaged', err: 'unknown recipe', id });
      const held = c.inv[rec.output.item] | 0;
      const cv = Crafting.validateSalvageCount(msg.count === undefined ? 1 : msg.count, held);
      if (!cv.ok) return c.send({ t: 'salvaged', err: cv.error, id });
      const salvageCount = cv.count;
      const refund = Crafting.batchSalvageRefund(rec.inputs, salvageCount, SALVAGE_REFUND_BPS);
      let inv = ECO.remove(c.inv, rec.output.item, salvageCount);
      for (const mat in refund) inv = ECO.add(inv, mat, refund[mat]);
      c.inv = inv;
      c.atkBoost = gearBonus(c.inv, 'weapon');
      stateSave(c);
      sendVitals(c);
      c.send({
        t: 'salvaged', id, item: rec.output.item, count: salvageCount, refund, inv: c.inv, atkBoost: c.atkBoost
      });
      break;
    }

    case 'tame': {
      if (!c.ready || c.dead) return;
      const mapPets = Pets.petsForMap(c.map);
      const petId = cleanText(msg.id, 32) || (mapPets[0] && mapPets[0].id) || '';
      const def = Pets.petOf(petId);
      if (def && c.pet && c.pet.owned && c.pet.owned[petId]) {
        return sendPet(c, { ok: false, err: 'already owned' });
      }
      const baitHeld = def && c.inv ? c.inv[def.bait] : 0;
      const v = Pets.validateTame({
        petId, map: c.map, baitHeld, nearSpeciesKind: def ? nearPetSpecies(c, def.speciesKind) : null
      });
      if (!v.ok) return sendPet(c, { ok: false, err: v.error });
      const cost = {}; cost[v.cost.item] = v.cost.qty;
      const paid = ECO.applyCost(c.inv, cost);
      if (!paid) return sendPet(c, { ok: false, err: 'need bait' });
      c.inv = paid;
      c.pet = Pets.applyTreat(c.pet || Pets.emptyState(), petId, Date.now());
      savePet(c);
      stateSave(c);
      sendPet(c, { ok: true });
      break;
    }

    case 'pet-treat': {
      if (!c.ready || c.dead) return;
      const petId = cleanText(msg.id, 32) || (c.pet && c.pet.out) || ownedList(c.pet)[0] || '';
      const def = Pets.petOf(petId);
      const v = Pets.validateTreat({
        petId,
        owned: !!(def && c.pet && c.pet.owned && c.pet.owned[petId]),
        out: (c.pet && c.pet.out) || null,
        itemHeld: def && c.inv ? c.inv[def.treatItem] : 0,
        pendingStratum: c.tokenPending | 0
      });
      if (!v.ok) return sendPet(c, { ok: false, err: v.error });
      const tcost = {}; tcost[v.pet.treatItem] = v.itemCost;
      const paid = ECO.applyCost(c.inv, tcost);
      if (!paid) return sendPet(c, { ok: false, err: 'need treat' });
      const led = ledgerOf(c.key);
      if ((led.pending | 0) < v.stratumCost) return sendPet(c, { ok: false, err: 'need stratum' });
      c.inv = paid;
      ledgerSave(c.key, (led.pending | 0) - v.stratumCost, led.claimed, led.wallet);
      c.tokenPending = (led.pending | 0) - v.stratumCost;
      // Treat STRATUM is a real sink: burn-split + GLDX earmark like every other
      // spend (the items are consumed above; this is the token half).
      const tSplit = applyBurnSplit(v.stratumCost);
      scheduleOnChainSink(tSplit.burned, Gldx.earmarkOf(tSplit.treasury));
      c.pet = Pets.applyTreat(c.pet || Pets.emptyState(), petId, Date.now());
      savePet(c);
      stateSave(c);
      sendPet(c, { ok: true });
      break;
    }

    case 'pet-park': {
      if (!c.ready || c.dead) return;
      c.pet = Pets.park(c.pet);
      savePet(c);
      sendPet(c, { ok: true });
      break;
    }

    case 'pet-out': {
      if (!c.ready || c.dead) return;
      const petId = cleanText(msg.id, 32) || ownedList(c.pet)[0] || '';
      if (!Pets.petOf(petId) || !(c.pet && c.pet.owned && c.pet.owned[petId])) {
        return sendPet(c, { ok: false, err: 'not owned' });
      }
      c.pet = { out: petId, lastTreatAt: (c.pet && c.pet.lastTreatAt) | 0, owned: Object.assign({}, (c.pet && c.pet.owned) || {}) };
      savePet(c);
      sendPet(c, { ok: true });
      break;
    }

    // Buy a premium companion for a fixed 50,000 pending STRATUM. Burn-split +
    // GLDX earmark like every sink; ownership merges into player_pets and the
    // new pet walks out immediately. Refusals touch nothing.
    case 'buy-pet': {
      if (!c.ready || !c.key) return;
      const petId = cleanText(msg.id, 32);
      const st = c.pet || Pets.emptyState();
      const owned = {};
      for (const k of Object.keys(st.owned || {})) if (st.owned[k]) owned[k] = true;
      const led = ledgerOf(c.key);
      const v = Pets.validatePetBuy(petId, led.pending | 0, owned);
      if (!v.ok) return sendPet(c, { ok: false, err: v.error });
      ledgerSave(c.key, (led.pending | 0) - v.price, led.claimed, led.wallet);
      c.tokenPending = (led.pending | 0) - v.price;
      const split = applyBurnSplit(v.price);
      scheduleOnChainSink(split.burned, Gldx.earmarkOf(split.treasury));
      owned[petId] = true;
      c.pet = { out: petId, lastTreatAt: st.lastTreatAt | 0, owned: owned };
      savePet(c);
      stateSave(c);
      sendPet(c, { ok: true, price: v.price, burned: split.burned, treasury: split.treasury });
      break;
    }

    case 'wallet-challenge': {
      if (!c.ready || !c.key) return;
      var wNow = Date.now();
      c.walletNonce = crypto.randomBytes(16).toString('hex');
      c.walletNonceAt = wNow;
      issueWalletNonce(c.walletNonce, wNow);
      c.send({ t: 'wallet-challenge', nonce: c.walletNonce });
      break;
    }

    // One wallet is one colonist. Play does not require this. Claim and convert do.
    // A signature is optional for a first link (tests and wallets that only expose
    // connect) and required to resume a colonist that already belongs to the wallet —
    // an unsigned address must never take over someone else's key.
    case 'wallet-link': {
      if (!c.ready || !c.key) return;
      const addr = (typeof msg.address === 'string') ? msg.address.trim() : '';
      if (!addr) {
        qWalletDelByKey.run(c.key);
        const cur0 = ledgerOf(c.key);
        c.tokenWallet = null;
        ledgerSave(c.key, cur0.pending, cur0.claimed, null);
        return c.send({
          t: 'wallet-linked', address: null, tokenPending: cur0.pending | 0,
          commerce: TokenConfig.publicConfig(COMMERCE), payout: payoutPublic()
        });
      }
      if (!TokenConfig.isAddr(addr)) {
        return c.send({ t: 'wallet-linked', err: 'invalid address' });
      }
      let proved = false;
      if (typeof msg.signature === 'string' && msg.signature.length) {
        const nonce = (typeof msg.nonce === 'string') ? msg.nonce : '';
        var linkNow = Date.now();
        // Per-connection freshness (2-min window, single-use) plus global
        // single-use & 5-min TTL. Both must pass — the per-connection check
        // preserves the existing "one socket, one challenge" guarantee, while
        // the global store prevents replay on a second socket with a sniffed
        // nonce. Either check failing is "signature rejected" — no detail leak.
        var fresh = c.walletNonce && nonce === c.walletNonce && (linkNow - c.walletNonceAt) < 120000;
        // Invalidate per-connection nonce immediately (single-use) before any
        // further test, so a second attempt with the same nonce fails even if
        // the global store race is slow.
        c.walletNonce = null;
        var globalFresh = consumeWalletNonce(nonce, linkNow);
        // Back-compat: a nonce issued before this deploy has no entry in the
        // new global store (e.g. server just restarted, client still holds a
        // pre-restart challenge). In that narrow window, honour the per-
        // connection freshness alone so the deploy does not break in-flight
        // handshakes — but never accept a nonce that fails both checks.
        // We treat "not in global store" as absence only when per-connection
        // was fresh and the global store had no record; if the nonce was
        // previously consumed globally, consumeWalletNonce returns false and
        // we must reject even if per-connection was fresh (replay).
        // Detection: fresh && !globalFresh but walletNonces had never contained
        // this nonce vs had and was consumed is indistinguishable after delete,
        // so we store "consumed" tombstone implicitly via `fresh` — if globalFresh
        // is false but `fresh` is true and the nonce matches the 32-hex format,
        // the safest no-break behaviour is: if per-connection matched, but
        // global says no, we still require global for NEW nonces (issued after
        // deploy). Since we now always issue into the global store, any
        // legit post-deploy nonce WILL be in the store before this check, so
        // fresh && !globalFresh after deploy is definitively a replay/expired.
        if (!fresh || !globalFresh || !WalletProof.verifyLink(addr, c.key, nonce, msg.signature)) {
          return c.send({ t: 'wallet-linked', err: 'signature rejected' });
        }
        proved = true;
      }
      const bound = qWalletGet.get(addr);
      if (bound && bound.k !== c.key) {
        if (!proved) {
          return c.send({ t: 'wallet-linked', err: 'wallet already belongs to another colonist' });
        }
        return c.send({
          t: 'wallet-linked', address: addr, resumeKey: bound.k,
          commerce: TokenConfig.publicConfig(COMMERCE), payout: payoutPublic()
        });
      }
      const mine = qWalletByKey.get(c.key);
      if (mine && mine.wallet !== addr) {
        return c.send({ t: 'wallet-linked', err: 'this colonist already has a wallet' });
      }
      if (!mine) qWalletIns.run(addr, c.key, Date.now());
      const cur = ledgerOf(c.key);
      c.tokenWallet = addr;
      ledgerSave(c.key, cur.pending, cur.claimed, c.tokenWallet);
      c.send({
        t: 'wallet-linked',
        address: c.tokenWallet,
        tokenPending: cur.pending | 0,
        commerce: TokenConfig.publicConfig(COMMERCE),
        payout: payoutPublic()
      });
      refreshHolderBonus(c); // fire-and-forget — see that function's header
      break;
    }

    // Player monuments (burn-heavy sink): 1,000 STRATUM through the split,
    // cap 3 per player, permanent like land. Must stand on your own claimed tile
    // within reach. The name ships to every visitor via the chunk feed.
    case 'monument-build': {
      if (!c.ready || !c.key) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return c.send({ t: 'monument-built', ok: false, err: 'bounds' });
      const dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'monument-built', ok: false, err: 'out of reach' });
      const tile = tiles.get(c.map + ':' + (y * W + x));
      if (!tile || tile.owner !== c.key) return c.send({ t: 'monument-built', ok: false, err: 'needs your claimed land' });
      const name = cleanText(msg.name, 24) || 'Monument';
      try {
        if ((qMonCount.get(c.key).n | 0) >= MONUMENT_CAP) {
          return c.send({ t: 'monument-built', ok: false, err: 'monument cap reached (' + MONUMENT_CAP + ')' });
        }
      } catch (e) { return c.send({ t: 'monument-built', ok: false, err: 'try again' }); }
      const led = ledgerOf(c.key);
      if ((led.pending | 0) < MONUMENT_COST) {
        return c.send({ t: 'monument-built', ok: false, err: 'need 1000 STRATUM pending', cost: MONUMENT_COST });
      }
      ledgerSave(c.key, (led.pending | 0) - MONUMENT_COST, led.claimed, led.wallet);
      c.tokenPending = (led.pending | 0) - MONUMENT_COST;
      const split = applyBurnSplit(MONUMENT_COST);
      scheduleOnChainSink(split.burned, Gldx.earmarkOf(split.treasury));
      const id = crypto.randomUUID();
      const now = Date.now();
      const mon = { id, owner: c.key, map: c.map, x, y, name };
      monuments.set(id, mon);
      qMonIns.run(id, c.key, c.map, x, y, name, now);
      stateSave(c);
      broadcastMonument(mon);
      c.send({ t: 'monument-built', ok: true, id, name, x, y, cost: MONUMENT_COST,
        burned: split.burned, treasury: split.treasury,
        tokenPending: c.tokenPending | 0, colonyQuota: burnedTotal() });
      break;
    }

    // Turn a player's pending STRATUM ledger balance into a claim attempt. This is the
    // ONE place src/chain-adapter.js gets called. Real SPL transfer code exists there
    // now, but it still answers 'not_configured' today because the mint is still the
    // placeholder sentinel (see README.md's Commerce note) — that gate lifts
    // automatically once a real STRATUM mint is set via STRATUM_TOKEN_MINT.
    // The pending balance is NEVER decremented on a 'not_configured' answer: nothing was
    // lost, the claim just sits recorded and queued, exactly as owed as it was before the
    // request. The async settle call is why this handler (alone, today) doesn't finish
    // synchronously — every other message in this switch still does.
    case 'claim': {
      if (!c.ready || !c.key) return;
      if (!c.tokenWallet) return c.send({ t: 'claimed', ok: false, err: 'link a wallet first' });
      if (claimsInFlight.has(c.key)) {
        return c.send({ t: 'claimed', ok: false, err: 'claim already in progress' });
      }
      const cur = ledgerOf(c.key);
      const amount = cur.pending | 0;
      if (amount <= 0) return c.send({ t: 'claimed', ok: false, err: 'nothing pending' });
      // Below MIN_CLAIM_AMOUNT: refuse before ever touching claim_requests or chain-
      // adapter.js — same "nothing spent on a refusal" contract as every other economy
      // gate in this file (requisition, rush, shop-buy). The pending balance is untouched;
      // the player just keeps earning until they clear the floor.
      const quote = Payout.quoteClaim(amount, CLAIM_FEE_BPS, MIN_CLAIM_AMOUNT);
      if (!quote.ok) {
        return c.send({
          t: 'claimed', ok: false, err: quote.error,
          minClaim: MIN_CLAIM_AMOUNT, tokenPending: amount,
          fee: quote.fee, payout: quote.payout
        });
      }
      const id = crypto.randomUUID();
      const wallet = c.tokenWallet, key = c.key, now = Date.now();
      const fee = quote.fee, payout = quote.payout;
      qClaimIns.run(id, key, wallet, amount, fee, payout, 'requested', null, null, now, null);
      claimsInFlight.add(key);
      // The chain transfer is the net payout. The fee stays in the treasury's
      // token account because it is never included in the transfer.
      ChainAdapter.settleClaim({ key, wallet, amountUnits: payout }, claimEnv()).then((res) => {
        if (res.ok) {
          const latest = ledgerOf(key);
          const claimed = (latest.claimed | 0) + payout;
          const pending = Math.max(0, (latest.pending | 0) - amount);
          ledgerSave(key, pending, claimed, latest.wallet);
          if (fee > 0) treasuryCredit('STRATUM', fee);
          qClaimUpdate.run('settled', null, res.txHash || null, Date.now(), id);
          notifyPlayer(key, {
            t: 'claimed', ok: true, amount, fee, payout, txHash: res.txHash,
            tokenPending: pending, tokenClaimed: claimed
          });
        } else {
          // Not configured, or the send failed: pending is unchanged and the fee
          // is not taken. The row stays as the audit trail.
          qClaimUpdate.run('queued', res.reason || null, null, null, id);
          notifyPlayer(key, {
            t: 'claimed', ok: false, queued: true, reason: res.reason, detail: res.detail,
            amount, fee, payout, tokenPending: ledgerOf(key).pending
          });
        }
      }).catch((e) => {
        qClaimUpdate.run('queued', 'internal_error', null, null, id);
        notifyPlayer(key, {
          t: 'claimed', ok: false, queued: true, reason: 'internal_error',
          amount, fee, payout, tokenPending: ledgerOf(key).pending
        });
      }).finally(() => { claimsInFlight.delete(key); });
      break;
    }

    // Pay a funded GLDX claim from the treasury's real GLDX. Never mints any.
    case 'claim-gldx': {
      if (!c.ready || !c.key) return;
      if (!c.tokenWallet) return c.send({ t: 'gldx-claimed', ok: false, err: 'link a wallet first' });
      const env = claimEnv();
      fundGldxClaims().then(() => {
        const g = ledgerOf(c.key);
        const pay = g.gldxPayable | 0;
        if (pay <= 0) {
          return c.send({
            t: 'gldx-claimed', ok: false, err: 'nothing ready — keep playing, or hold STRATUM while others ship',
            gldxPending: g.gldxPending | 0, gldxPayable: 0,
            gldxText: Gldx.format(g.gldxPending | 0), gldxReadyText: '0'
          });
        }
        return ChainAdapter.transferRaw(c.tokenWallet, Gldx.GLDX_MINT, String(pay), Gldx.DECIMALS, env).then((res) => {
          if (!res.ok) {
            return c.send({
              t: 'gldx-claimed', ok: false, err: res.detail || res.reason || 'send failed',
              gldxPending: g.gldxPending | 0, gldxPayable: pay,
              gldxText: Gldx.format(g.gldxPending | 0), gldxReadyText: Gldx.format(pay)
            });
          }
          qGldxSet.run(g.gldxPending | 0, 0, Date.now(), c.key);
          c.gldxPending = g.gldxPending | 0;
          c.gldxPayable = 0;
          c.send({
            t: 'gldx-claimed', ok: true, txHash: res.txHash, paid: pay, paidText: Gldx.format(pay),
            gldxPending: c.gldxPending, gldxPayable: 0,
            gldxText: Gldx.format(c.gldxPending), gldxReadyText: '0'
          });
        });
      }).catch(() => {
        try { c.send({ t: 'gldx-claimed', ok: false, err: 'could not read the treasury' }); } catch (e) {}
      });
      break;
    }

    // Gold <-> pending STRATUM. Wallet required. Fee is STRATUM added to the treasury
    // vault. This does not broadcast a chain transaction — claim is the only
    // path that moves STRATUM onto a wallet.
    case 'convert': {
      if (!c.ready || !c.key) return;
      if (!c.tokenWallet) {
        return c.send({
          t: 'converted', ok: false, err: 'link a wallet first',
          tokenPending: (ledgerOf(c.key).pending | 0), gold: (c.inv && c.inv.gold) | 0
        });
      }
      const dir = msg.dir === 'to-gold' ? 'to-gold' : (msg.dir === 'to-token' ? 'to-token' : '');
      if (!dir) return c.send({ t: 'converted', ok: false, err: 'bad direction' });
      const led = ledgerOf(c.key);
      const gold = (c.inv && c.inv.gold) | 0;
      const pending = led.pending | 0;
      const amount = (msg.amount === undefined) ? undefined
        : (isFin(msg.amount) ? Math.trunc(msg.amount) : -1);
      const q = Payout.quoteConvert(dir, amount, { gold: gold, pending: pending }, {
        feeBps: CONVERT_FEE_BPS, goldPerStrm: GOLD_PER_STRM, minStrm: MIN_CONVERT_AMOUNT
      });
      if (!q.ok) {
        return c.send({
          t: 'converted', ok: false, err: q.error, dir: dir,
          tokenPending: pending, gold: gold, minConvert: MIN_CONVERT_AMOUNT
        });
      }
      const newPending = dir === 'to-token' ? (pending + q.payout) : (pending - q.gross);
      const newGold = dir === 'to-token' ? (gold - q.spentGold) : (gold + q.goldOut);
      ledgerSave(c.key, newPending, led.claimed, led.wallet);
      c.tokenPending = newPending;
      c.inv.gold = newGold;
      if (q.fee > 0) treasuryCredit('STRATUM', q.fee);
      qConvertIns.run(crypto.randomUUID(), c.key, c.tokenWallet, dir, q.gross, q.fee, q.payout, Date.now());
      stateSave(c);
      c.send({
        t: 'converted', ok: true, dir: dir, gross: q.gross, fee: q.fee, payout: q.payout,
        spentGold: q.spentGold, goldOut: q.goldOut,
        tokenPending: newPending, gold: newGold, inv: c.inv
      });
      break;
    }

    // Vanity wardrobe: buy a STRATUM-priced cosmetic with pending STRATUM. Pure
    // vanity (zero stats) and a real burn sink — price funnels through
    // applyBurnSplit like every other sink, and the treasury slice is earmarked
    // for the GLDX swap like requisition's. Buying unlocks; set-look equips.
    // Refusals never touch the ledger or ownership.
    case 'buy-vanity': {
      if (!c.ready || !c.key) return;
      const itemId = cleanText(msg.id, 32);
      const led = ledgerOf(c.key);
      const pending = led.pending | 0;
      const owned = vanityOwned(c.key);
      const v = CU.validateVanityBuy(itemId, pending, owned);
      if (!v.ok) {
        return c.send({ t: 'vanity-bought', ok: false, err: v.error, id: itemId,
          price: v.price, tokenPending: pending });
      }
      const qNewPending = pending - v.price;
      ledgerSave(c.key, qNewPending, led.claimed, led.wallet);
      c.tokenPending = qNewPending;
      qVanityIns.run(c.key, itemId, Date.now());
      const qSplit = applyBurnSplit(v.price);
      scheduleOnChainSink(qSplit.burned, Gldx.earmarkOf(qSplit.treasury));
      stateSave(c);
      c.send({
        t: 'vanity-bought', ok: true, id: itemId, price: v.price,
        burned: qSplit.burned, treasury: qSplit.treasury,
        tokenPending: qNewPending, colonyQuota: burnedTotal()
      });
      break;
    }

    // Will refill: restore will to full for a flat STRATUM price. Repeatable,
    // capped (full will refuses), same burn-split + GLDX earmark as every sink.
    case 'refill-will': {
      if (!c.ready || !c.key) return;
      if ((c.energy | 0) >= ENERGY_MAX) {
        return c.send({ t: 'will-filled', ok: false, err: 'will already full',
          energy: c.energy | 0, cost: WILL_REFILL_COST, tokenPending: ledgerOf(c.key).pending | 0 });
      }
      const led = ledgerOf(c.key);
      const pending = led.pending | 0;
      if (pending < WILL_REFILL_COST) {
        return c.send({ t: 'will-filled', ok: false, err: 'cannot afford',
          energy: c.energy | 0, cost: WILL_REFILL_COST, tokenPending: pending });
      }
      const qNewPending = pending - WILL_REFILL_COST;
      ledgerSave(c.key, qNewPending, led.claimed, led.wallet);
      c.tokenPending = qNewPending;
      c.energy = ENERGY_MAX;
      const qSplit = applyBurnSplit(WILL_REFILL_COST);
      scheduleOnChainSink(qSplit.burned, Gldx.earmarkOf(qSplit.treasury));
      stateSave(c);
      sendVitals(c);
      c.send({
        t: 'will-filled', ok: true, energy: c.energy | 0, cost: WILL_REFILL_COST,
        burned: qSplit.burned, treasury: qSplit.treasury,
        tokenPending: qNewPending, colonyQuota: burnedTotal()
      });
      break;
    }

    // Settler tithes: a standing order for +10% reward yield. Entry is a flat
    // 50,000 pending STRATUM, 100% to the treasury (collector, not burn — the
    // recurring weekly upkeep is the burn side). Cancel is free; lapse on
    // unaffordable upkeep weeks is silent-ish (a notice, never a seizure).
    case 'tithe-start': {
      if (!c.ready || !c.key) return;
      const settler = cleanText(msg.settler, 16);
      const led = ledgerOf(c.key);
      const pending = led.pending | 0;
      const v = Tithes.validateStart(settler, pending, titheSettlers(c.key));
      if (!v.ok) {
        return c.send({ t: 'tithe-started', ok: false, err: v.error, settler: settler,
          price: v.price, tokenPending: pending, tithes: titheSettlers(c.key) });
      }
      ledgerSave(c.key, pending - v.price, led.claimed, led.wallet);
      c.tokenPending = pending - v.price;
      const now = Date.now();
      qTitheIns.run(c.key, settler, now, now);
      treasuryCredit('STRATUM', v.price);
      stateSave(c);
      c.send({ t: 'tithe-started', ok: true, settler: settler, price: v.price,
        tokenPending: c.tokenPending | 0, tithes: titheSettlers(c.key) });
      break;
    }

    case 'tithe-cancel': {
      if (!c.ready || !c.key) return;
      const settler = cleanText(msg.settler, 16);
      qTitheDel.run(c.key, settler);
      c.send({ t: 'tithe-cancelled', ok: true, settler: settler, tithes: titheSettlers(c.key) });
      break;
    }

    // Discover a wonder site: one-time STRATUM + XP per player per site. Must
    // stand on the same map within reach of the resolved site tile. Repeat
    // visits answer ok:false (already found) — never double-pay.
    case 'discover': {
      if (!c.ready || !c.key) return;
      const siteId = cleanText(msg.site, 32);
      const site = Landmarks.siteOf(siteId);
      if (!site || site.map !== c.map) {
        return c.send({ t: 'discovered', ok: false, err: 'no such wonder here', site: siteId });
      }
      const at = resolveSite(c.map, site);
      if (!at) return c.send({ t: 'discovered', ok: false, err: 'no such wonder here', site: siteId });
      const dx = at.x - c.x, dy = at.y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) {
        return c.send({ t: 'discovered', ok: false, err: 'walk closer to discover', site: siteId });
      }
      const found = foundSites(c.key);
      if (found.indexOf(siteId) !== -1) {
        return c.send({ t: 'discovered', ok: false, err: 'already discovered', site: siteId, found: found });
      }
      qFoundIns.run(c.key, siteId, Date.now());
      const led = ledgerOf(c.key);
      ledgerSave(c.key, (led.pending | 0) + site.reward, led.claimed, led.wallet);
      c.tokenPending = (led.pending | 0) + site.reward;
      world.awardXp(c, site.xp);
      stateSave(c);
      sendVitals(c);
      c.send({ t: 'discovered', ok: true, site: siteId, name: site.name, lore: site.lore,
        reward: site.reward, xp: site.xp, tokenPending: c.tokenPending | 0, found: foundSites(c.key) });
      break;
    }

    // Vault deposit: move pending STRATUM into the stake. 1% entry fee straight
    // to treasury. Omit amount to stake everything pending.
    case 'vault-deposit': {
      if (!c.ready || !c.key) return;
      const led = ledgerOf(c.key);
      const pending = led.pending | 0;
      const amount = (msg.amount === undefined) ? pending
        : (isFin(msg.amount) ? Math.trunc(msg.amount) : -1);
      const v = Vault.validateDeposit(amount, pending);
      if (!v.ok) {
        return c.send({ t: 'vault-deposited', ok: false, err: v.error,
          vault: vaultBalance(c.key), tokenPending: pending });
      }
      ledgerSave(c.key, pending - v.gross, led.claimed, led.wallet);
      c.tokenPending = pending - v.gross;
      const now = Date.now();
      qVaultSet.run(c.key, vaultBalance(c.key) + v.net, now);
      if (v.fee > 0) treasuryCredit('STRATUM', v.fee);
      stateSave(c);
      c.send({ t: 'vault-deposited', ok: true, gross: v.gross, fee: v.fee, net: v.net,
        vault: vaultBalance(c.key), tokenPending: c.tokenPending | 0 });
      break;
    }

    // Vault withdraw: stake back to pending minus the 2.5% exit fee to treasury.
    // Omit amount to withdraw everything.
    case 'vault-withdraw': {
      if (!c.ready || !c.key) return;
      const bal = vaultBalance(c.key);
      const amount = (msg.amount === undefined) ? bal
        : (isFin(msg.amount) ? Math.trunc(msg.amount) : -1);
      const v = Vault.validateWithdraw(amount, bal);
      if (!v.ok) {
        return c.send({ t: 'vault-withdrawn', ok: false, err: v.error,
          vault: bal, tokenPending: ledgerOf(c.key).pending | 0 });
      }
      const led = ledgerOf(c.key);
      qVaultSet.run(c.key, bal - v.gross, Date.now());
      ledgerSave(c.key, (led.pending | 0) + v.net, led.claimed, led.wallet);
      c.tokenPending = (led.pending | 0) + v.net;
      if (v.fee > 0) treasuryCredit('STRATUM', v.fee);
      stateSave(c);
      c.send({ t: 'vault-withdrawn', ok: true, gross: v.gross, fee: v.fee, net: v.net,
        vault: vaultBalance(c.key), tokenPending: c.tokenPending | 0 });
      break;
    }

    // Earth Requisition. Default path spends pending on the ledger (tests, and any
    // host that has not turned STRATUM_SINK_ONCHAIN on). Live path spends claimed
    // STRATUM from the linked wallet: the mint taxes the transfer, then 80% of what
    // arrives is burned on-chain and 20% stays in the treasury. Pending is left
    // alone — it is the float you earn before a claim, not a supply burn.
    case 'requisition': {
      if (!c.ready || !c.key) return;
      if (sinkOnChainLive()) {
        handleOnChainRequisition(c, msg);
        break;
      }
      const qled = ledgerOf(c.key);
      const pending = qled.pending | 0;
      if (msg.amount === undefined && pending <= 0) {
        return c.send({ t: 'requisitioned', ok: false, err: 'nothing pending', tokenPending: pending });
      }
      // omit `amount` to ship everything currently pending; otherwise it must be a real
      // positive integer. clampInt is deliberately NOT used here — it clamps an
      // out-of-range value INTO range (0 would become 1), which would silently accept
      // "requisition 0" as "requisition 1"; a bad amount must be refused outright, not
      // rounded up into a real spend the player never asked for.
      const amount = (msg.amount === undefined) ? pending
        : (isFin(msg.amount) ? Math.trunc(msg.amount) : -1);
      const v = TokenSink.validateRequisition(amount, pending);
      if (!v.ok) return c.send({ t: 'requisitioned', ok: false, err: v.error, tokenPending: pending });
      const qNewPending = pending - v.amount;
      ledgerSave(c.key, qNewPending, qled.claimed, qled.wallet);
      c.tokenPending = qNewPending;
      const qSplit = applyBurnSplit(v.amount);
      scheduleOnChainSink(qSplit.burned, Gldx.earmarkOf(qSplit.treasury));
      stateSave(c);
      const quota = burnedTotal();
      c.send({
        t: 'requisitioned', ok: true, amount: v.amount, burned: qSplit.burned, treasury: qSplit.treasury,
        tokenPending: qNewPending, colonyQuota: quota, onChain: false
      });
      // A big requisition is a moment worth other colonists seeing — same spirit as an
      // emote, purely cosmetic, no gameplay effect for anyone but the shipper.
      if (v.amount >= 50) {
        for (const o of clients.values()) {
          if (o.ready && o.key !== c.key) o.send({ t: 'requisition-broadcast', by: c.name, amount: v.amount, colonyQuota: quota });
        }
      }
      checkAchievements(c);
      break;
    }

    case 'toolup': {
      if (!c.ready || c.dead) return;
      const next = (c.tool | 0) + 1;
      const cost = ECO.toolCost(next);
      const tier = ECO.toolTier(next);
      if (!cost || !tier) return c.send({ t: 'tooled', err: 'already at the best tools' });
      if (!ECO.canAfford(c.inv, cost)) {
        return c.send({ t: 'tooled', err: 'not enough resources', need: cost, missing: ECO.missingFor(c.inv, cost) });
      }
      const paid = ECO.applyCost(c.inv, cost);
      if (!paid) return c.send({ t: 'tooled', err: 'not enough resources', need: cost, missing: ECO.missingFor(c.inv, cost) });
      c.inv = paid;
      c.tool = next;
      stateSave(c);
      sendVitals(c);
      c.send({ t: 'tooled', tool: next, name: tier.name, inv: c.inv });
      checkAchievements(c);
      break;
    }

    case 'build-structure': {
      if (!c.ready || c.dead) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return c.send({ t: 'built', err: 'bounds' });
      const kind = cleanText(msg.kind, 16);
      const def = Idle.structureOf(kind);
      if (!def) return c.send({ t: 'built', err: 'unknown structure', kind });
      const dx = x - c.x, dy = y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'built', err: 'reach', x, y });
      // a structure needs a claimed tile under it — this is what keeps land ownership
      // meaningful under cozy rules even without combat/scarcity driving it.
      const tile = tiles.get(c.map + ':' + (y * W + x));
      if (!tile || tile.owner !== c.key) return c.send({ t: 'built', err: 'needs your own claimed land', x, y });
      const skey = structKey(c.map, x, y);
      if (structures.has(skey)) return c.send({ t: 'built', err: 'already built here', x, y });
      if (def.tier > (c.tool | 0)) return c.send({ t: 'built', err: 'locked: needs better tools', kind });
      const cost = Idle.buildCost(kind);
      if (!cost || !ECO.canAfford(c.inv, cost)) {
        return c.send({ t: 'built', err: 'not enough resources', need: cost, missing: cost ? ECO.missingFor(c.inv, cost) : undefined, kind });
      }
      const paid = ECO.applyCost(c.inv, cost);
      if (!paid) return c.send({ t: 'built', err: 'not enough resources', need: cost, kind });
      const now = Date.now();
      const struct = Idle.makeStructure(skey, kind, c.map, x, y, c.key, now);
      if (!struct) return c.send({ t: 'built', err: 'internal' });
      c.inv = paid;
      structures.set(skey, struct);
      qStruct.run(struct.id, struct.kind, struct.map, struct.x, struct.y, struct.owner, struct.builtAt, struct.lastCollectedAt);
      stateSave(c);
      broadcastStructure(c.map, x, y, struct);
      c.send({ t: 'built', kind, x, y, id: struct.id, inv: c.inv });
      refreshBuilderBonus(c); // owned count just changed — src/builder-bonus.js
      checkAchievements(c);
      break;
    }

    case 'collect-structure': {
      if (!c.ready || c.dead) return;
      let skey;
      if (isFin(msg.x) && isFin(msg.y)) {
        const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
        if (x === null || y === null) return c.send({ t: 'collected', err: 'bounds' });
        skey = structKey(c.map, x, y);
      } else {
        const id = cleanText(msg.id, 64);
        if (!id) return c.send({ t: 'collected', err: 'no structure there' });
        skey = id;
      }
      const struct = structures.get(skey);
      if (!struct || struct.map !== c.map) return c.send({ t: 'collected', err: 'no structure there' });
      if (struct.owner !== c.key) return c.send({ t: 'collected', err: 'not yours' });
      // Reach is enforced for consistency with every other tile-targeted interaction —
      // a structure being passive makes it less critical (nobody else can drain it),
      // but "walk up, collect" keeps the same loop as harvesting a node or a drop.
      const dx = struct.x - c.x, dy = struct.y - c.y;
      if (dx * dx + dy * dy > REACH * REACH) return c.send({ t: 'collected', err: 'reach', x: struct.x, y: struct.y });
      const now = Date.now();
      const res = Idle.collect(struct, c.inv, now);
      c.inv = res.inv;
      let pay = { gold: 0, token: 0 };
      if (res.gained > 0) pay = applyCommerceReward(c, 'collect', { kind: struct.kind });
      structures.set(skey, res.struct);
      qStruct.run(res.struct.id, res.struct.kind, res.struct.map, res.struct.x, res.struct.y, res.struct.owner, res.struct.builtAt, res.struct.lastCollectedAt);
      stateSave(c);
      c.send({
        t: 'collected', x: struct.x, y: struct.y, gained: res.gained, resource: res.resource,
        inv: c.inv, gains: { gold: pay.gold, token: pay.token }, tokenPending: c.tokenPending | 0
      });
      if (res.gained > 0) checkAchievements(c);
      break;
    }

    // Pay STRATUM to instantly finish a structure's current batch instead of waiting.
    // The already-accrued portion still goes through Idle.collect() exactly like an
    // ordinary collect; the rushed remainder is a straight purchase, credited the same
    // uncapped way idle.js's own collect() credits a resource. STRATUM is deducted BEFORE
    // anything is granted — a spend that fails partway must never hand out free goods.
    case 'structure-rush': {
      if (!c.ready || c.dead) return;
      if (sinkOnChainLive()) {
        handleOnChainRush(c, msg);
        break;
      }
      const info = quoteRushFor(c, msg);
      if (info.err) return c.send({ t: 'rushed', err: info.err, x: info.x, y: info.y });
      const rled = ledgerOf(c.key);
      if ((rled.pending | 0) < info.quote.cost) {
        return c.send({ t: 'rushed', err: 'cannot afford', cost: info.quote.cost, tokenPending: rled.pending | 0 });
      }
      const rNewPending = (rled.pending | 0) - info.quote.cost;
      ledgerSave(c.key, rNewPending, rled.claimed, rled.wallet);
      c.tokenPending = rNewPending;
      const rSplit = applyBurnSplit(info.quote.cost);
      scheduleOnChainSink(rSplit.burned, Gldx.earmarkOf(rSplit.treasury));
      const rRes = applyRushFill(c, info);
      c.send({
        t: 'rushed', x: info.struct.x, y: info.struct.y, resource: info.def.produces,
        gained: rRes.gained + info.quote.gained, cost: info.quote.cost, burned: rSplit.burned, treasury: rSplit.treasury,
        inv: c.inv, tokenPending: c.tokenPending, tokenBurned: burnedTotal(), onChain: false
      });
      if (rRes.gained + info.quote.gained > 0) checkAchievements(c);
      break;
    }

    // Tear down a structure you own — same named-verb pattern as 'release' does for a
    // claimed tile (no refund, just handing the ground back). This is the only removal
    // path for a structure; a wall you no longer want goes through here, same as every
    // idle producer already could have, had anyone needed to remove one before now.
    case 'release-structure': {
      if (!c.ready || c.dead) return;
      if (!isFin(msg.x) || !isFin(msg.y)) return c.send({ t: 'structure-released', err: 'no structure there' });
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return c.send({ t: 'structure-released', err: 'bounds' });
      const dstruct = structures.get(structKey(c.map, x, y));
      if (!dstruct || dstruct.map !== c.map) return c.send({ t: 'structure-released', err: 'no structure there' });
      if (dstruct.owner !== c.key) return c.send({ t: 'structure-released', err: 'not yours' });
      const ddx = dstruct.x - c.x, ddy = dstruct.y - c.y;
      if (ddx * ddx + ddy * ddy > REACH * REACH) return c.send({ t: 'structure-released', err: 'reach', x: dstruct.x, y: dstruct.y });
      structures.delete(structKey(c.map, x, y));
      qStructDel.run(dstruct.id);
      broadcastStructureGone(c.map, dstruct.x, dstruct.y);
      c.send({ t: 'structure-released', x: dstruct.x, y: dstruct.y, kind: dstruct.kind });
      refreshBuilderBonus(c); // owned count just changed — src/builder-bonus.js
      break;
    }

    // ---- shops: sell from your own claimed land, DB-escrowed, no direct scam surface ----
    case 'shop-list': {
      if (!c.ready || c.dead) return;
      const x = inBounds(msg.x, W), y = inBounds(msg.y, H);
      if (x === null || y === null) return c.send({ t: 'shop-listed', err: 'bounds' });
      const rdx = x - c.x, rdy = y - c.y;
      if (rdx * rdx + rdy * rdy > REACH * REACH) return c.send({ t: 'shop-listed', err: 'out of reach' });
      const tile = tiles.get(c.map + ':' + (y * W + x));
      if (!tile || tile.owner !== c.key) return c.send({ t: 'shop-listed', err: 'not your land' });

      const item = cleanText(msg.item, 32);
      const priceItem = cleanText(msg.priceItem, 32);
      const qty = clampInt(msg.qty, 1, Shops.MAX_QTY, -1);
      const priceQty = clampInt(msg.priceQty, 1, Shops.MAX_QTY, -1);
      const v = Shops.validListing(item, qty, priceItem, priceQty);
      if (!v.ok) return c.send({ t: 'shop-listed', err: v.error });
      // Only real catalog entries may be listed or priced — a made-up key would let a
      // player "sell" an item that doesn't exist and be paid in one that doesn't either.
      const knownItem = (k) => ECO.RESOURCES.indexOf(k) !== -1 || !!ECO.itemOf(k);
      if (!knownItem(item)) return c.send({ t: 'shop-listed', err: 'unknown item' });
      if (!knownItem(priceItem)) return c.send({ t: 'shop-listed', err: 'unknown price item' });

      // Listing fee (treasury collector): a flat STRATUM price per new listing,
      // 100% to the treasury like every other commerce fee. Proof-of-play gating
      // is the point — a listing costs something earned, so spam listings cost
      // real effort. Refused listings touch nothing (same contract as every gate).
      if (LISTING_FEE > 0) {
        const led = ledgerOf(c.key);
        if ((led.pending | 0) < LISTING_FEE) {
          return c.send({ t: 'shop-listed', err: 'listing fee: need ' + LISTING_FEE + ' STRATUM pending',
            listingFee: LISTING_FEE, tokenPending: led.pending | 0 });
        }
        ledgerSave(c.key, (led.pending | 0) - LISTING_FEE, led.claimed, led.wallet);
        c.tokenPending = (led.pending | 0) - LISTING_FEE;
        treasuryCredit('STRATUM', LISTING_FEE);
      }

      const escrowed = Shops.escrow(c.inv, item, qty);
      if (!escrowed) return c.send({ t: 'shop-listed', err: 'not enough ' + dispKey(item) });
      c.inv = escrowed;                        // the goods leave live inventory THE MOMENT the listing exists
      const id = crypto.randomUUID();
      const now = Date.now();
      const listing = { id, seller: c.key, map: c.map, x, y, item, qty, priceItem, priceQty, createdAt: now };
      shopListings.set(id, listing);
      qShopIns.run(id, c.key, c.map, x, y, item, qty, priceItem, priceQty, now);
      stateSave(c);
      c.send({ t: 'shop-listed', id, listing, inv: c.inv, listingFee: LISTING_FEE, tokenPending: c.tokenPending | 0 });
      break;
    }

    case 'shop-buy': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 64);
      const listing = shopListings.get(id);
      if (!listing) return c.send({ t: 'shop-bought', id, err: 'no such listing' });
      if (listing.map !== c.map) return c.send({ t: 'shop-bought', id, err: 'wrong map' });
      const bdx = listing.x - c.x, bdy = listing.y - c.y;
      if (bdx * bdx + bdy * bdy > REACH * REACH) return c.send({ t: 'shop-bought', id, err: 'out of reach' });
      if (listing.seller === c.key) return c.send({ t: 'shop-bought', id, err: 'cannot buy your own listing' });
      const buyQty = clampInt(msg.qty, 1, Shops.MAX_QTY, 1);
      const res = Shops.buy(listing, c.inv, buyQty, SHOP_FEE_BPS);
      if (!res.ok) return c.send({ t: 'shop-bought', id, err: res.error });

      // one atomic step: buyer's payment leaves, the seller's already-escrowed goods
      // arrive, the seller gets its price-minus-fee (online or not) and the treasury
      // gets the fee — never partially, same split parcel-buy already does below.
      c.inv = res.buyerInv;
      listing.qty = res.remainingQty;
      if (listing.qty <= 0) {
        shopListings.delete(id);
        qShopDel.run(id);
      } else {
        qShopIns.run(id, listing.seller, listing.map, listing.x, listing.y, listing.item, listing.qty, listing.priceItem, listing.priceQty, listing.createdAt);
      }
      creditPlayer(listing.seller, listing.priceItem, res.sellerGets);
      treasuryCredit(listing.priceItem, res.treasuryGets);
      stateSave(c);
      c.send({ t: 'shop-bought', id, bought: buyQty, item: listing.item, cost: res.cost, fee: res.treasuryGets, priceItem: listing.priceItem, remainingQty: listing.qty, inv: c.inv });
      notifyPlayer(listing.seller, { t: 'shop-sold', id, buyer: c.key, item: listing.item, qty: buyQty, cost: res.sellerGets, priceItem: listing.priceItem });
      break;
    }

    case 'shop-cancel': {
      if (!c.ready) return;
      const id = cleanText(msg.id, 64);
      const listing = shopListings.get(id);
      if (!listing) return c.send({ t: 'shop-cancelled', id, err: 'no such listing' });
      if (listing.seller !== c.key) return c.send({ t: 'shop-cancelled', id, err: 'not your listing' });
      shopListings.delete(id);
      qShopDel.run(id);
      // whatever was still in escrow — sold or not — returns to the seller. A seller
      // cancelling can only ever be the one connected right now (sending this message
      // requires a live socket), so this credits them directly rather than via creditPlayer.
      if (listing.qty > 0) gain(c, listing.item, listing.qty);
      stateSave(c);
      c.send({ t: 'shop-cancelled', id, returned: { [listing.item]: listing.qty }, inv: c.inv });
      break;
    }

    // ---- direct player trade: addressed offers only, escrowed both ways ----
    case 'trade-offer': {
      if (!c.ready || c.dead) return;
      const to = (typeof msg.to === 'string') ? msg.to.slice(0, 64) : '';
      if (!to || !KEY_RE.test(to)) return c.send({ t: 'trade-offered', err: 'bad recipient' });
      if (to === c.key) return c.send({ t: 'trade-offered', err: 'cannot trade with yourself' });
      // Never trust the client's bare claim of who this is for: the key must belong to a
      // player who has actually connected before — the same qPlayGet lookup 'hello'
      // itself relies on as the one source of truth for "this key is a real player".
      if (!qPlayGet.get(to)) return c.send({ t: 'trade-offered', err: 'unknown player' });

      const giveItem = cleanText(msg.giveItem, 32);
      const giveQty = clampInt(msg.giveQty, 1, 1000000, -1);
      const wantItemRaw = cleanText(msg.wantItem, 32);
      const wantQtyRaw = clampInt(msg.wantQty, 1, 1000000, -1);
      const v = Trade.validOffer(giveItem, giveQty, wantItemRaw || null, wantItemRaw ? wantQtyRaw : 0);
      if (!v.ok) return c.send({ t: 'trade-offered', err: v.error });

      const knownItem2 = (k) => ECO.RESOURCES.indexOf(k) !== -1 || !!ECO.itemOf(k);
      if (!knownItem2(giveItem)) return c.send({ t: 'trade-offered', err: 'unknown item' });
      if (v.wantItem && !knownItem2(v.wantItem)) return c.send({ t: 'trade-offered', err: 'unknown want item' });

      const escrowed = Trade.escrowGive(c.inv, giveItem, giveQty);
      if (!escrowed) return c.send({ t: 'trade-offered', err: 'not enough ' + dispKey(giveItem) });
      c.inv = escrowed;                        // A's give-side leaves live inventory THE MOMENT the offer exists

      const id = crypto.randomUUID();
      const now = Date.now();
      const offer = { id, from: c.key, to, giveItem, giveQty, wantItem: v.wantItem, wantQty: v.wantQty, createdAt: now, ttlMs: TRADE_TTL_MS };
      tradeOffers.set(id, offer);
      qTradeIns.run(id, c.key, to, giveItem, giveQty, v.wantItem, v.wantQty, now, TRADE_TTL_MS);
      stateSave(c);
      c.send({ t: 'trade-offered', id, offer, inv: c.inv });
      notifyPlayer(to, { t: 'trade-incoming', id, offer });
      break;
    }

    case 'trade-accept': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 64);
      const offer = tradeOffers.get(id);
      if (!offer) return c.send({ t: 'trade-accepted', id, err: 'no such offer' });
      if (offer.to !== c.key) return c.send({ t: 'trade-accepted', id, err: 'not addressed to you' });
      const now = Date.now();
      if (Trade.expired(offer, now)) {
        // lazily swept here too, not only on the slow tick: an acceptor should never hear
        // "no such offer" when the real reason is "too late" — the escrow return is
        // identical either way, so this reuses the exact expiry-return path below.
        tradeOffers.delete(id);
        qTradeDel.run(id);
        if (offer.giveQty > 0) creditPlayer(offer.from, offer.giveItem, offer.giveQty);
        return c.send({ t: 'trade-accepted', id, err: 'expired' });
      }
      const res = Trade.accept(offer, c.inv);
      if (!res.ok) return c.send({ t: 'trade-accepted', id, err: res.error });

      // one atomic step: whatever B owes leaves B, A's already-escrowed gift/give arrives
      // in B, and A is credited (online or not) — never partially, per Trade.accept's contract.
      c.inv = res.accepterInv;
      tradeOffers.delete(id);
      qTradeDel.run(id);
      if (res.paid > 0) creditPlayer(offer.from, offer.wantItem, res.paid);
      stateSave(c);
      const paidOut = res.paid > 0 ? { [offer.wantItem]: res.paid } : null;
      c.send({ t: 'trade-accepted', id, received: { [offer.giveItem]: offer.giveQty }, paid: paidOut, inv: c.inv });
      notifyPlayer(offer.from, { t: 'trade-completed', id, by: c.key, paid: paidOut });
      break;
    }

    case 'trade-cancel': {
      if (!c.ready) return;
      const id = cleanText(msg.id, 64);
      const offer = tradeOffers.get(id);
      if (!offer) return c.send({ t: 'trade-cancelled', id, err: 'no such offer' });
      if (offer.from !== c.key) return c.send({ t: 'trade-cancelled', id, err: 'not your offer' });
      tradeOffers.delete(id);
      qTradeDel.run(id);
      // only the offerer can cancel, and cancelling requires a live socket, so this
      // credits the (necessarily online) caller directly rather than via creditPlayer.
      if (offer.giveQty > 0) gain(c, offer.giveItem, offer.giveQty);
      stateSave(c);
      c.send({ t: 'trade-cancelled', id, returned: { [offer.giveItem]: offer.giveQty }, inv: c.inv });
      break;
    }

    // ---- parcel deeds: user-priced land market, settled by the system ----
    // A deed is a named view over the minter's own contiguous claimed tiles. Minting
    // moves nothing (no escrow — the owner keeps everything until an atomic sale).
    case 'parcel-mint': {
      if (!c.ready || c.dead) return;
      const raw = Array.isArray(msg.tiles) ? msg.tiles : null;
      if (!raw || raw.length > Parcels.MAX_DEED_TILES) return c.send({ t: 'parcel-minted', err: 'bad tiles' });
      const clean = [];
      for (const t of raw) {
        const x = inBounds(t && t.x, W), y = inBounds(t && t.y, H);
        if (x === null || y === null) return c.send({ t: 'parcel-minted', err: 'bounds' });
        clean.push({ x, y });
      }
      const v = Parcels.validateDeed(clean, msg.name);
      if (!v.ok) return c.send({ t: 'parcel-minted', err: v.error });
      // every tile must be claimed land owned by the minter, on the map they stand on
      for (const t of v.tiles) {
        const tile = tiles.get(c.map + ':' + (t.y * W + t.x));
        if (!tile || tile.owner !== c.key) return c.send({ t: 'parcel-minted', err: 'not all tiles are your land' });
      }
      // no tile may already sit inside another deed — otherwise one sale corrupts two deeds
      const taken = deedTileSet();
      for (const t of v.tiles) {
        if (taken.has(c.map + ':' + t.x + ':' + t.y)) return c.send({ t: 'parcel-minted', err: 'tile already in a deed' });
      }
      const id = crypto.randomUUID();
      const now = Date.now();
      const deed = { id, owner: c.key, map: c.map, name: v.name, tiles: v.tiles, createdAt: now };
      parcels.set(id, deed);
      qParcelIns.run(id, c.key, c.map, v.name, JSON.stringify(v.tiles), now);
      c.send({ t: 'parcel-minted', id, deed: { id, map: c.map, name: v.name, tiles: v.tiles, bbox: Parcels.bbox(v.tiles) } });
      break;
    }

    case 'parcel-list': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 64);
      const deed = parcels.get(id);
      if (!deed) return c.send({ t: 'parcel-listed', id, err: 'no such deed' });
      if (deed.owner !== c.key) return c.send({ t: 'parcel-listed', id, err: 'not your deed' });
      const priceItem = cleanText(msg.priceItem, 32);
      const priceQty = clampInt(msg.priceQty, 1, Parcels.MAX_QTY, -1);
      const v = Parcels.validListing(priceItem, priceQty);
      if (!v.ok) return c.send({ t: 'parcel-listed', id, err: v.error });
      const knownItem = (k) => ECO.RESOURCES.indexOf(k) !== -1 || !!ECO.itemOf(k) || k === 'gold';
      if (!knownItem(priceItem)) return c.send({ t: 'parcel-listed', id, err: 'unknown price item' });
      const now = Date.now();
      const listing = { id, seller: c.key, map: deed.map, priceItem, priceQty, createdAt: now };
      parcelListings.set(id, listing);
      qParcelListIns.run(id, c.key, deed.map, priceItem, priceQty, now);
      c.send({ t: 'parcel-listed', id, listing });
      break;
          }

          case 'parcel-buy': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 64);
      const listing = parcelListings.get(id);
      if (!listing) return c.send({ t: 'parcel-bought', id, err: 'no such listing' });
      if (listing.map !== c.map) return c.send({ t: 'parcel-bought', id, err: 'wrong map' });
      if (listing.seller === c.key) return c.send({ t: 'parcel-bought', id, err: 'cannot buy your own listing' });
      // must be within REACH of the parcel's bounding box center (or any tile in it)
      const deed = parcels.get(id);
      if (!deed) return c.send({ t: 'parcel-bought', id, err: 'deed missing' });
      // check reach to bbox center
      const bb = Parcels.bbox(deed.tiles);
      if (!bb) return c.send({ t: 'parcel-bought', id, err: 'bad deed' });
      const cx = bb.x0 + (bb.w - 1) / 2, cy = bb.y0 + (bb.h - 1) / 2;
      const bdx = cx - c.x, bdy = cy - c.y;
      if (bdx * bdx + bdy * bdy > REACH * REACH) return c.send({ t: 'parcel-bought', id, err: 'out of reach' });
      const res = Parcels.swapDeed(c.inv, listing.priceItem, listing.priceQty, PARCEL_FEE_BPS);
      if (!res.ok) return c.send({ t: 'parcel-bought', id, err: res.error });
      // atomic: buyer pays, deed + all tiles flip, seller gets price-fee, treasury gets fee
      c.inv = res.buyerInv;
      // flip ownership of all tiles in the deed
      for (const t of deed.tiles) {
        const key = deed.map + ':' + (t.y * W + t.x);
        const tile = tiles.get(key);
        if (tile) {
          tile.owner = c.key;
          tiles.set(key, tile);
          qTile.run(deed.map, t.x, t.y, tile.m, c.key, Date.now());
        }
      }
      // transfer deed ownership
      deed.owner = c.key;
      qParcelIns.run(deed.id, c.key, deed.map, deed.name, JSON.stringify(deed.tiles), deed.createdAt);
      // delist
      parcelListings.delete(id);
      qParcelListDel.run(id);
      // credit seller (price - fee) and treasury (fee)
      creditPlayer(listing.seller, listing.priceItem, res.sellerGets);
      treasuryCredit(listing.priceItem, res.treasuryGets);
      stateSave(c);
      c.send({ t: 'parcel-bought', id, priceItem: listing.priceItem, priceQty: listing.priceQty, fee: res.treasuryGets, deed: { id: deed.id, name: deed.name, map: deed.map, bbox: Parcels.bbox(deed.tiles) }, inv: c.inv });
      notifyPlayer(listing.seller, { t: 'parcel-sold', id, buyer: c.key, priceItem: listing.priceItem, priceQty: listing.priceQty, fee: res.treasuryGets });
      break;
    }

    case 'parcel-cancel': {
      if (!c.ready) return;
      const id = cleanText(msg.id, 64);
      const listing = parcelListings.get(id);
      if (!listing) return c.send({ t: 'parcel-cancelled', id, err: 'no such listing' });
      if (listing.seller !== c.key) return c.send({ t: 'parcel-cancelled', id, err: 'not your listing' });
      parcelListings.delete(id);
      qParcelListDel.run(id);
      c.send({ t: 'parcel-cancelled', id });
      break;
    }

    case 'parcel-browse': {
      if (!c.ready) return;
      const map = clampInt(msg.map, 0, T.MAPS.length - 1, c.map);
      const out = [];
      for (const listing of parcelListings.values()) {
        if (listing.map !== map) continue;
        const deed = parcels.get(listing.id);
        if (!deed) continue;
        out.push({
          id: listing.id,
          name: deed.name,
          map: listing.map,
          priceItem: listing.priceItem,
          priceQty: listing.priceQty,
          tiles: deed.tiles.length,
          bbox: Parcels.bbox(deed.tiles),
          seller: listing.seller
        });
      }
      c.send({ t: 'parcel-browse', map, list: out });
      break;
    }

    case 'parcel-mine': {
      if (!c.ready) return;
      const out = [];
      for (const d of parcels.values()) {
        if (d.owner !== c.key) continue;
        const listing = parcelListings.get(d.id);
        out.push({
          id: d.id,
          name: d.name,
          map: d.map,
          tiles: d.tiles.length,
          bbox: Parcels.bbox(d.tiles),
          listed: !!listing,
          listing: listing ? { priceItem: listing.priceItem, priceQty: listing.priceQty, createdAt: listing.createdAt } : null
        });
      }
      c.send({ t: 'parcel-mine', list: out });
      break;
    }

    // ---- emote wheel: fixed allowlist, never freeform text (no-chat non-goal) ----
    case 'emote': {
      if (!c.ready || c.dead) return;
      const id = cleanText(msg.id, 24);
      if (EMOTES.indexOf(id) === -1) return c.send({ t: 'emote', err: 'unknown emote' });
      for (const o of clients.values()) {
        if (!o.ready || o.map !== c.map) continue;
        if (Math.abs(o.x - c.x) > 80 || Math.abs(o.y - c.y) > 80) continue;
        o.send({ t: 'emote', key: c.key, name: c.name, x: c.x, y: c.y, id });
      }
      break;
    }

    case 'map': {
      if (!c.ready) return;
      // Never densFor() an id the world does not have: that would allocate a fresh grid
      // per invented map number, which is a cheap way to eat all the memory we have.
      let map = (msg.map === undefined) ? c.map : clampInt(msg.map, 0, 1024, c.map);
      if (!T.MAPS.some(m => m.id === map)) map = c.map;
      const d = densFor(map);
      c.send({ t: 'map', map, grid: MAPGRID, step: MAPSTEP, d: Buffer.from(d).toString(B64), claimed: countClaims(map) });
      break;
    }

    case 'set-look': {
      if (!c.ready) return;
      // Never trust the client's claim to own an accessory: validateLook re-checks every
      // slot against this player's ACTUAL unlocked-achievement state, same as every other
      // player-controlled field gets re-validated server-side.
      const requested = (msg && typeof msg === 'object')
        ? { paletteId: msg.paletteId, hat: msg.hat, cloak: msg.cloak, scarf: msg.scarf,
            visor: msg.visor, pack: msg.pack, patch: msg.patch } : {};
      const look = CU.validateLook(requested, [...c.achIds], vanityOwned(c.key));
      const pal = CU.paletteOf(look.paletteId) || CU.paletteOf(CU.DEFAULT_PALETTE_ID);
      c.paletteId = pal.id; c.bodyHue = pal.bodyHue; c.trimHue = pal.trimHue;
      c.accessories = { hat: look.hat, cloak: look.cloak, scarf: look.scarf, visor: look.visor, pack: look.pack, patch: look.patch };
      qLook.run(c.paletteId, c.bodyHue, c.trimHue, JSON.stringify(c.accessories), c.key);
      c.send({
        t: 'look', paletteId: c.paletteId, bodyHue: c.bodyHue, trimHue: c.trimHue,
        hat: c.accessories.hat, cloak: c.accessories.cloak, scarf: c.accessories.scarf,
        visor: c.accessories.visor, pack: c.accessories.pack, patch: c.accessories.patch
      });
      break;
    }

    case 'ping': {
      // echoed, but bounded: a client must not be able to make us repeat a payload back
      const echo = isFin(msg.c) ? Math.trunc(msg.c) : (cleanText(msg.c, 32) || null);
      c.send({ t: 'pong', c: echo });
      break;
    }
  }
}

function broadcastNode(map, x, y, kind, state, ripeSec) {
  const cx = T.chunkOf(x), cy = T.chunkOf(y), k = subKey(map, cx, cy);
  for (const c of clients.values()) if (c.ready && c.subs.has(k)) c.send({ t: 'node', map, x, y, kind, state, ripeSec });
}
/** A monument was raised — tell chunk subscribers so visitors see it live. */
function broadcastMonument(mon) {
  const cx = T.chunkOf(mon.x), cy = T.chunkOf(mon.y), k = subKey(mon.map, cx, cy);
  for (const c of clients.values()) {
    if (c.ready && c.subs.has(k)) {
      c.send({ t: 'monument', id: mon.id, owner: mon.owner, map: mon.map, x: mon.x, y: mon.y, name: mon.name });
    }
  }
}

// ---------- ticks ----------------------------------------------------------
// Every timer body is wrapped: a fault in one tick (or in one client's data) must cost
// us that tick, not the world. Repeated faults log at most once per 5s so a throwing
// condition can never be turned into a log flood.
function every(ms, label, fn) {
  let lastLog = 0;
  setInterval(() => {
    try { fn(); }
    catch (e) {
      const now = Date.now();
      if (now - lastLog > 5000) { lastLog = now; console.log(`[err] ${label}:`, e && (e.stack || e.message)); }
    }
  }, ms);
}

every(REGEN_MS, 'energy regen', () => {
  for (const c of clients.values()) {
    if (c.ready) c.energy = Math.min(ENERGY_MAX, c.energy + 1);
  }
});

// world simulation: monsters move, fight, respawn; depleted nodes come back
every(100, 'world tick', () => {
  const ps = ready().filter(c => !c.dead);
  if (!ps.length) return;
  const now = Date.now();
  const ev = world.tick(ps, now);

  for (const r of ev.revived) {
    broadcastNode(r.map, r.x, r.y, r.kind, 1, 0);
    for (const c of ps) {
      if (c.map !== r.map || !Pets.ripePing(c.pet, now)) continue;
      const dx = c.x - r.x, dy = c.y - r.y;
      if (dx * dx + dy * dy > 48 * 48) continue;
      c.send({ t: 'pet-ping', x: r.x, y: r.y, map: r.map });
    }
  }
  for (const m of ev.respawned) {
    for (const c of clients.values()) if (c.ready && c.map === m.map) c.send({ t: 'mon', id: m.id, kind: m.kind, x: m.x, y: m.y, hp: 1, maxHp: 1, spawn: true });
  }

  // Ambient kills (Sanctuary maps): world.tick() already ran the same grantLoot/awardXp
  // machinery attack() uses (see world.js's killMonster) — this just does the same
  // bookkeeping+notification server.js's own 'attack' handler does on a Frontier kill.
  for (const k of ev.ambientKills) {
    for (const c of clients.values()) {
      if (!c.ready || c.key !== k.key) continue;
      c.kills += 1;
      c.atk = BASE_ATK + Math.floor(c.kills / 3);
      gain(c, k.loot, 1);
      stateSave(c);
      c.send({ t: 'combat', id: k.id, killed: true, name: k.name, loot: k.loot, kills: c.kills, atk: c.atk, inv: c.inv, level: k.level });
      checkAchievements(c);
    }
  }

  for (const h of ev.hits) {
    for (const c of clients.values()) {
      if (!c.ready || c.key !== h.key) continue;
      // worn armour soaks part of the blow, never below 1: being hit always costs.
      const dealt = Math.max(1, h.dmg - gearBonus(c.inv, 'armour'));
      c.hp -= dealt;
      if (c.hp <= 0) {
        // death costs half your raw resources, spilled where you fell — gear is never touched
        const dMap = c.map;
        const dx2 = Math.max(0, Math.min(W - 1, Math.round(c.x)));
        const dy2 = Math.max(0, Math.min(H - 1, Math.round(c.y)));
        const split = Drops.dropsForDeath(c.inv);
        c.inv = split.kept;
        if (Drops.totalIn({ res: split.dropped }) > 0) {
          const drop = world.addDrop(dMap, dx2, dy2, split.dropped, now, Drops.DEFAULT_TTL_MS);
          if (drop) broadcastDrop(dMap, dx2, dy2, drop);
        }
        c.hp = c.maxHp; c.dead = false;
        const sp = T.spawnPoint(c.map);
        c.x = sp.x; c.y = sp.y;
        c.sent.clear(); c.subs = new Set();
        stateSave(c);
        c.send({ t: 'died', by: h.name, spawn: sp, hp: c.hp, maxHp: c.maxHp, inv: c.inv });
        setView(c, c.x, c.y);
        console.log(`[net] ${c.name} was killed by ${h.name}`);
      } else {
        c.send({ t: 'dmg', dmg: dealt, by: h.name, hp: Math.round(c.hp), maxHp: c.maxHp });
      }
    }
  }
});

// presence + nearby monsters at 10Hz
every(100, 'presence tick', () => {
  const all = ready();
  if (!all.length) return;
  for (const c of all) {
    const near = [];
    for (const o of all) {
      if (o === c || o.map !== c.map) continue;
      if (Math.abs(o.x - c.x) > 72 || Math.abs(o.y - c.y) > 72) continue;
      near.push([o.key, o.name, Math.round(o.x * 10) / 10, Math.round(o.y * 10) / 10, o.bodyHue, o.trimHue,
        o.accessories.hat, o.accessories.cloak, o.accessories.scarf,
        o.accessories.visor, o.accessories.pack, o.accessories.patch]);
      if (near.length >= 64) break;
    }
    c.send({ t: 'players', list: near, you: [Math.round(c.x * 10) / 10, Math.round(c.y * 10) / 10, c.energy] });
    const pets = [];
    for (const o of all) {
      if (o === c || o.map !== c.map) continue;
      if (Math.abs(o.x - c.x) > 72 || Math.abs(o.y - c.y) > 72) continue;
      const pw = petWire(o);
      if (pw) pets.push(pw);
      if (pets.length >= 64) break;
    }
    c.send({ t: 'pets', list: pets });
    c.send({ t: 'mons', map: c.map, list: world.nearby(c.map, c.x, c.y) });
  }
});

// death drops: TTL sweep. A drop nobody is near to see removed does not need to be
// swept faster than this — the client that walks up simply never gets 'drop' for it.
every(5000, 'drop sweep', () => {
  const gone = world.sweepExpiredDrops(Date.now());
  for (const g of gone) broadcastDropGone(g.map, g.x, g.y);
});

// trade offer TTL sweep: an offer nobody accepted in time returns its escrow to the
// offerer (online or not) — same lazy/periodic-sweep shape as the drop-sweep above,
// applied to trade_offers instead of the drops table.
every(5000, 'trade sweep', () => {
  const now = Date.now();
  for (const [id, offer] of [...tradeOffers]) {
    if (!Trade.expired(offer, now)) continue;
    tradeOffers.delete(id);
    qTradeDel.run(id);
    if (offer.giveQty > 0) creditPlayer(offer.from, offer.giveItem, offer.giveQty);
    notifyPlayer(offer.from, { t: 'trade-expired', id, returned: { [offer.giveItem]: offer.giveQty } });
  }
});

// tithe upkeep sweep (hourly cadence, weekly dues): each due tithe takes its week
// from pending via the standard burn-split (+GLDX earmark like every sink), or
// lapses silently when unaffordable. Lapse, never seizure — the entry fee bought
// the option, not an obligation.
const qTitheUpkeep = db.prepare('UPDATE tithes SET lastUpkeepAt=? WHERE k=? AND settler=?');
// Land upkeep + quota dividends, weekly. Upkeep burns 2/tile (capped) from
// pending — a baseline drain scaling with land, not sessions. Dividends recycle
// treasury fee income to landholders pro-rata (capped by the vault, 2.5% fee
// stays in the vault). NEVER seizes land: short upkeep just burns what exists.
const UPKEEP_PER_TILE = Number(process.env.STRATUM_UPKEEP_PER_TILE) > 0
  ? Number(process.env.STRATUM_UPKEEP_PER_TILE) | 0 : 2;
const UPKEEP_WEEKLY_CAP = Number(process.env.STRATUM_UPKEEP_WEEKLY_CAP) > 0
  ? Number(process.env.STRATUM_UPKEEP_WEEKLY_CAP) | 0 : 2000;
const DIV_PER_TILE = Number(process.env.STRATUM_DIV_PER_TILE) > 0
  ? Number(process.env.STRATUM_DIV_PER_TILE) | 0 : 1;
const qTreasurySet = db.prepare('UPDATE treasury SET qty=?, updated=? WHERE item=?');
// Hourly in production; STRATUM_TITHE_SWEEP_MS shortens it for tests (min 1s).
const TITHE_SWEEP_MS = Math.max(1000, Number(process.env.STRATUM_TITHE_SWEEP_MS) > 0
  ? Number(process.env.STRATUM_TITHE_SWEEP_MS) | 0 : 3600000);
every(TITHE_SWEEP_MS, 'tithe upkeep', () => {
  const now = Date.now();
  let rows;
  try { rows = qTitheDue.all(); } catch (e) { return; }
  for (const r of rows) {
    if (!Tithes.upkeepDue(r, now).due) continue;
    const led = ledgerOf(r.k);
    const s = Tithes.settleUpkeep(led.pending | 0, TITHE_WEEKLY);
    if (!s.ok) {
      qTitheDel.run(r.k, r.settler);
      notifyPlayer(r.k, { t: 'tithe-lapsed', settler: r.settler });
      continue;
    }
    ledgerSave(r.k, (led.pending | 0) - s.paid, led.claimed, led.wallet);
    const split = applyBurnSplit(s.paid);
    scheduleOnChainSink(split.burned, Gldx.earmarkOf(split.treasury));
    qTitheUpkeep.run(now, r.k, r.settler);
    notifyPlayer(r.k, { t: 'tithe-kept', settler: r.settler, paid: s.paid,
      burned: split.burned, treasury: split.treasury, tokenPending: ledgerOf(r.k).pending | 0 });
  }
  // Vault emission: once per week, split the fixed GLDX pool pro-rata across
  // depositors into their gldxPending (fundGldxClaims moves it payable when the
  // on-chain treasury can actually cover it — same cap as play earnings).
  try {
    const week = Math.floor(now / Vault.WEEK_MS);
    if (counterOf('vault_kitty_week') !== week) {
      counterSet('vault_kitty_week', week);
      const depRows = qVaultAll.all().map(x => ({ key: x.k, balance: x.balance | 0 }));
      const shares = Vault.emissionShares(depRows, VAULT_WEEKLY_GLDX);
      for (const sh of shares) {
        if (sh.share > 0) creditGldx(sh.key, sh.share);
      }
      if (shares.length) console.log(`[vault] weekly emission: ${VAULT_WEEKLY_GLDX} GLDX raw across ${shares.length} depositor(s)`);
    }
  } catch (e) { console.log('[vault] emission skipped:', e && e.message); }
  // Land upkeep + dividends: once per week, on the same cadence. Upkeep burns
  // from pending (capped, never seizes); dividends pay landholders from the
  // treasury vault pro-rata (capped by balance, fee stays in the vault).
  try {
    const week = Math.floor(now / Vault.WEEK_MS);
    if (counterOf('upkeep_week') !== week) {
      counterSet('upkeep_week', week);
      let burnedW = 0, paidW = 0;
      for (const [key, tiles] of ownerCounts) {
        if (!(tiles > 0)) continue;
        const owed = Math.min(UPKEEP_PER_TILE * tiles, UPKEEP_WEEKLY_CAP);
        if (owed <= 0) continue;
        const led = ledgerOf(key);
        const take = Math.min(owed, led.pending | 0);
        if (take > 0) {
          ledgerSave(key, (led.pending | 0) - take, led.claimed, led.wallet);
          qBurnUpsert.run('global', burnedTotal() + take, now);
          burnedW += take;
        }
      }
      const vaultBal = (treasuryTotals().STRATUM | 0);
      let totalTiles = 0;
      for (const [, tiles] of ownerCounts) totalTiles += tiles;
      if (vaultBal > 0 && totalTiles > 0) {
        const grossEach = DIV_PER_TILE;
        // scale down if the vault cannot cover every tile at full rate
        const scale = Math.min(1, vaultBal / (grossEach * totalTiles));
        let paid = 0;
        for (const [key, tiles] of ownerCounts) {
          if (!(tiles > 0)) continue;
          const gross = Math.floor(grossEach * tiles * scale);
          if (gross <= 0) continue;
          const fee = Math.floor((gross * CONVERT_FEE_BPS) / Payout.FEE_DENOM);
          const net = gross - fee;
          if (net <= 0) continue;
          const led = ledgerOf(key);
          ledgerSave(key, (led.pending | 0) + net, led.claimed, led.wallet);
          paid += net;
          notifyPlayer(key, { t: 'dividend', net: net, tokenPending: (led.pending | 0) + net });
        }
        if (paid > 0) {
          const cur = treasuryTotals().STRATUM | 0;
          qTreasurySet.run(Math.max(0, cur - paid), now, 'STRATUM');
          paidW = paid;
        }
      }
      counterSet('upkeep_week_burned', burnedW);
      counterSet('upkeep_week_divs', paidW);
      if (burnedW > 0 || paidW > 0) console.log(`[upkeep] week: burned ${burnedW}, dividends ${paidW}`);
    }
  } catch (e) { console.log('[upkeep] week skipped:', e && e.message); }
});

every(5000, 'stats tick', () => {
  const n = live();
  if (!n) return;
  const quota = burnedTotal();
  const colonyMultiplier = ColonyMilestone.multiplierFor(quota);
  for (const c of clients.values()) {
    if (!c.ready) continue;
    c.send({
      t: 'stats', claimed: countClaims(c.map), total: W * H, online: n, volatile: world.stats(),
      colonyQuota: quota, colonyMultiplier, vaultTvl: vaultStats().tvl
    });
  }
});

every(20000, 'state flush', () => {
  const now = Date.now();
  for (const c of clients.values()) if (c.ready && c.key) { qPlayLast.run(now, c.key); stateSave(c); achSave(c); }
});

// Idle sweep: sockets that have gone quiet are closed. This is what defeats slowloris —
// half-open connections cannot be parked here indefinitely. The read deadline is short
// before the handshake and generous after it, so a player who is simply standing still
// is never punished for it (the keepalive below keeps them counted as alive).
every(5000, 'idle sweep', () => {
  const now = Date.now();
  for (const c of [...clients.values()]) {
    if (c.gone) continue;
    if (now - c.lastRx > (c.ready ? IDLE_MS : HS_IDLE_MS)) dropClient(c, 'idle timeout');
  }
});

// WebSocket keepalive: browsers answer a ping frame themselves, so a "connected" client
// whose link has silently died stops looking alive within one ping interval.
every(WS_PING_MS, 'ws keepalive', () => {
  for (const c of clients.values()) {
    if (c.gone || !c.ready) continue;
    try { c.sock.write(wsEncode('', OP_PING)); } catch (e) {}
  }
});

// ---------- process safety net ---------------------------------------------
// One bad frame, one bad tick, one bad socket must never end the world. A shared
// persistent world that goes down is worse than any single fault, so these log loudly
// and keep serving.
process.on('uncaughtException', (e) => {
  try { console.log('[fatal] uncaughtException (still serving):', e && (e.stack || e.message)); } catch (_) {}
});
process.on('unhandledRejection', (r) => {
  try { console.log('[fatal] unhandledRejection (still serving):', (r && (r.stack || r.message)) || r); } catch (_) {}
});

// Test hook (see test-hardening.js): proves the net above really does keep the process
// serving after a fault. Never set in production.
if (process.env.STRATUM_TEST_THROW === '1') {
  setTimeout(() => { throw new Error('STRATUM_TEST_THROW: deliberate fault'); }, 700);
}

// ---------- shutdown -------------------------------------------------------
// Graceful: checkpoint every live player, say a proper goodbye on the wire, stop
// accepting, checkpoint the WAL and close SQLite before the process goes.
let shuttingDown = false;
function shutdown(sig) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`\n[world] ${sig} — sealing world…`);
  try { for (const c of clients.values()) if (c.ready && c.key) { stateSave(c); achSave(c); } }
  catch (e) { console.log('[err] shutdown state flush:', e && e.message); }
  try {
    for (const c of clients.values()) {
      try { c.sock.write(closeFrame(1001, 'server shutting down')); c.sock.end(); } catch (e) {}
    }
  } catch (e) {}
  try { server.close(); } catch (e) {}
  try { db.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (e) {}
  try { db.close(); }
  catch (e) { console.log('[err] db.close:', e && e.message); }
  try { process.exit(0); } catch (e) {}
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

server.listen(PORT, HOST, () => {
  console.log(`[world] STRATUM listening on http://${HOST === '0.0.0.0' ? '<lan-ip>' : HOST}:${PORT} (all interfaces)`);
  console.log(`[world] local: http://127.0.0.1:${PORT}`);
  console.log(`[world] ${T.MAPS.length} maps, each ${W}x${H} = ${(W * H).toLocaleString()} tiles`);
  for (const m of T.MAPS) {
    const sp = T.spawnPoint(m.id);
    console.log(`[world]   #${m.id} ${m.name} (seed ${m.seed}) spawn ${sp.x},${sp.y} — ${m.desc}`);
  }
  console.log(`[volatile] ${JSON.stringify(world.stats())}`);
  const ready = ChainAdapter.describe(claimEnv());
  console.log(`[commerce] ${COMMERCE.symbol} mint ${COMMERCE.tokenMint}` +
    (COMMERCE.placeholder ? ' (placeholder mint)' : '') +
    ` on ${COMMERCE.chainName} ${COMMERCE.cluster}`);
  console.log(`[commerce] treasury ${COMMERCE.treasuryAddress}`);
  console.log(`[commerce] fees parcel=${PARCEL_FEE_BPS}bps shop=${SHOP_FEE_BPS}bps claim=${CLAIM_FEE_BPS}bps convert=${CONVERT_FEE_BPS}bps`);
  console.log(`[commerce] settlement live=${ChainAdapter.isConfigured(claimEnv())}` +
    ` rpc=${ready.rpcConfigured} mint=${ready.mintConfigured}` +
    ` treasury=${ready.treasuryConfigured} signer=${ready.signerPresent}` +
    ` implemented=${ready.settlementImplemented}` +
    ` sinkOnChain=${SINK_ONCHAIN}`);
  if (ready.signerAddress) console.log(`[commerce] signer wallet ${ready.signerAddress}`);
});
